// Night 6 — checkout. The finale. Reads every flag from nights 1–5; sets only final_* and small night-6 flags.
NIGHTS.push({
  id: 6,
  title: { en: 'Night six', ru: 'Ночь шестая', uk: 'Ніч шоста', es: 'Sexta noche' },
  scenes: [
    {
      time: '23:00', name: { en: 'The drawer', ru: 'Ящик стола', uk: 'Шухляда', es: 'El cajón' }, voice: { gender: 'm', pitch: 0.75, rate: 0.92 },
      portrait: objectPortrait('#3a2a1a', '—'), start: 'a',
      nodes: {
        a: { who: 'narr', text: { en: "Night six. Sal's schedule by the register ends tonight; the column after it is blank. You open the drawer.", ru: 'Шестая ночь. График Сэла у кассы заканчивается сегодня; следующая колонка пустая. Вы открываете ящик.', uk: 'Шоста ніч. Графік Села біля каси закінчується сьогодні; наступна колонка порожня. Ви відкриваєте шухляду.', es: 'Sexta noche. El horario de Sal junto a la caja termina esta noche; la columna siguiente está en blanco. Abre el cajón.' },
             next: (s) => (s.flags.has_key ? 'key' : s.flags.took_photos ? 'photos' : (s.flags.reyes_card || s.flags.informant || s.flags.told_reyes) ? 'card' : 'empty') },
        key: { who: 'narr', text: (s) => s.flags.took_photos
              ? { en: 'A brass key, tag 12. Under it, the photographs from the wall upstairs, face down, the way you left them.', ru: 'Латунный ключ, бирка 12. Под ним фотографии со стены наверху, лицом вниз, как вы их оставили.', uk: 'Латунний ключ, бирка 12. Під ним фотографії зі стіни нагорі, лицем донизу, як ви їх залишили.', es: 'Una llave de latón, chapa 12. Debajo, las fotografías de la pared de arriba, boca abajo, tal como las dejó.' }
              : { en: "A brass key, tag 12. It has been in this drawer for three nights and it still doesn't look like it belongs to anything.", ru: 'Латунный ключ, бирка 12. Три ночи он лежит в этом ящике и всё ещё не похож на ключ от чего-то настоящего.', uk: 'Латунний ключ, бирка 12. Три ночі він лежить у цій шухляді й досі не схожий на ключ від чогось справжнього.', es: 'Una llave de latón, chapa 12. Lleva tres noches en este cajón y sigue sin parecer la llave de nada.' },
             choices: [
               { text: { en: 'Put the key in your pocket.', ru: 'Положить ключ в карман.', uk: 'Покласти ключ у кишеню.', es: 'Guardarse la llave en el bolsillo.' }, next: 'thu', effect: { flags: { key_pocket: true } } },
               { text: { en: 'Leave it where it is.', ru: 'Оставить, где лежит.', uk: 'Лишити, де лежить.', es: 'Dejarla donde está.' }, next: 'thu' },
             ] },
        photos: { who: 'narr', text: { en: 'No key. But the photographs are there: seventeen night clerks, one lamp, one desk. There was a gap on the wall upstairs, at eye level. You know who it is for.', ru: 'Ключа нет. Но фотографии на месте: семнадцать ночных портье, одна лампа, одна стойка. На стене наверху был пробел, на уровне глаз. Вы знаете, для кого он.', uk: 'Ключа немає. Але фотографії на місці: сімнадцять нічних портьє, одна лампа, одна стійка. На стіні нагорі була прогалина, на рівні очей. Ви знаєте, для кого вона.', es: 'No hay llave. Pero las fotografías siguen ahí: diecisiete recepcionistas de noche, una lámpara, un mostrador. En la pared de arriba había un hueco, a la altura de los ojos. Sabe para quién es.' }, next: 'thu' },
        card: { who: 'narr', text: { en: "Reyes's card, one corner bent. Nothing else. You know the number by heart now, which is its own kind of problem.", ru: 'Визитка Рейес, угол загнут. Больше ничего. Номер вы уже знаете наизусть, и это отдельная проблема.', uk: 'Візитівка Реєс, кутик загнутий. Більше нічого. Номер ви вже знаєте напам’ять, і це окрема проблема.', es: 'La tarjeta de Reyes, con una esquina doblada. Nada más. Ya se sabe el número de memoria, y eso es otro tipo de problema.' }, next: 'thu' },
        empty: { who: 'narr', text: { en: 'Empty. Six nights, and the drawer is empty. That took work.', ru: 'Пусто. Шесть ночей, и ящик пуст. Это стоило усилий.', uk: 'Порожньо. Шість ночей, і шухляда порожня. Це коштувало зусиль.', es: 'Vacío. Seis noches, y el cajón está vacío. Eso ha costado trabajo.' }, next: 'thu' },
        thu: { who: 'narr', text: (s) => s.flags.denis_call
              ? { en: "'Or come up before Friday,' Denis said on the phone. The calendar by the couch still says Friday; nobody has turned the page. Somebody has circled it.", ru: '«Или поднимитесь до пятницы», сказал Денис по телефону. Календарь у дивана всё ещё показывает пятницу; страницу никто не перевернул. Кто-то обвёл её.', uk: '«Або підніміться до п’ятниці», сказав Денис по телефону. Календар біля дивана досі показує п’ятницю; сторінку ніхто не перегорнув. Хтось її обвів.', es: '«O suba antes del viernes», dijo Denis por teléfono. El calendario junto al sofá sigue marcando viernes; nadie ha pasado la hoja. Alguien lo ha rodeado con un círculo.' }
              : { en: 'The calendar by the couch still says Friday; nobody has turned the page. Somebody has circled it in pencil, hard enough to tear the paper.', ru: 'Календарь у дивана всё ещё показывает пятницу; страницу никто не перевернул. Кто-то обвёл её карандашом так сильно, что порвал бумагу.', uk: 'Календар біля дивана досі показує п’ятницю; сторінку ніхто не перегорнув. Хтось обвів її олівцем так сильно, що порвав папір.', es: 'El calendario junto al sofá sigue marcando viernes; nadie ha pasado la hoja. Alguien lo ha rodeado a lápiz, con tanta fuerza que ha rasgado el papel.' },
             next: 'end' },
      }
    },
    {
      name: { en: 'Marv, room 7', ru: 'Марв, номер 7', uk: 'Марв, номер 7', es: 'Marv, habitación 7' }, voice: { gender: 'm', pitch: 0.85, rate: 0.9 },
      portrait: portrait('#4a5a6a', false, false), start: 'a',
      nodes: {
        a: { who: 'guest', effect: (s) => (s.flags.paid_marv ? { flags: { marv_thanked: true } } : {}), text: (s) => ((t) => (s.flags.paid_marv && !s.flags.marv_thanked ? { en: "Somebody paid my week. Sal says it wasn't him. …Thank you. Don't say anything. " + t.en, ru: "Кто-то оплатил мою неделю. Сэл говорит, не он. …Спасибо. Ничего не говорите. " + t.ru, uk: "Хтось оплатив мій тиждень. Сел каже, не він. …Дякую. Нічого не кажіть. " + t.uk, es: "Alguien me pagó la semana. Sal dice que no fue él. …Gracias. No diga nada. " + t.es } : t))(s.flags.met_denis
              ? { en: "Can't sleep. Nobody in this building has slept since Friday. …You went up. You walk different. …Anyway. Got a letter. My sister. A room in her house, past the river.", ru: 'Не спится. В этом доме никто не спал с пятницы. …Вы поднимались наверх. Походка другая. …Ладно. Письмо пришло. От сестры. Комната у неё в доме, за рекой.', uk: 'Не спиться. У цьому будинку ніхто не спав із п’ятниці. …Ви піднімалися нагору. Хода інша. …Гаразд. Лист прийшов. Від сестри. Кімната в неї в будинку, за річкою.', es: 'No puedo dormir. En este edificio nadie duerme desde el viernes. …Usted subió. Camina distinto. …En fin. Me llegó una carta. Mi hermana. Una habitación en su casa, pasado el río.' }
              : s.flags.marv_told
              ? { en: "Can't sleep. Denis went up on a Friday; I never told you that part. …Got a letter. My sister. A room in her house, past the river.", ru: 'Не спится. Денис поднялся в пятницу; эту часть я вам не рассказывал. …Письмо пришло. От сестры. Комната у неё в доме, за рекой.', uk: 'Не спиться. Денис піднявся в п’ятницю; цієї частини я вам не розповідав. …Лист прийшов. Від сестри. Кімната в неї в будинку, за річкою.', es: 'No puedo dormir. Denis subió un viernes; esa parte nunca se la conté. …Me llegó una carta. Mi hermana. Una habitación en su casa, pasado el río.' }
              : { en: "Can't sleep. …Got a letter. My sister. A room in her house, out past the river. Twenty years here. I'd need someone to say it's fine to go.", ru: 'Не спится. …Письмо пришло. От сестры. Комната у неё в доме, за рекой. Двадцать лет здесь. Мне нужно, чтобы кто-то сказал, что уехать — это нормально.', uk: 'Не спиться. …Лист прийшов. Від сестри. Кімната в неї в будинку, за річкою. Двадцять років тут. Мені треба, щоб хтось сказав, що поїхати — це нормально.', es: 'No puedo dormir. …Me llegó una carta. Mi hermana. Una habitación en su casa, al otro lado del río. Veinte años aquí. Necesitaría que alguien me dijera que está bien irse.' }),
             choices: (s) => [
               { text: { en: '"Go, Marv. This place is finished."', ru: '«Езжай, Марв. Этому месту конец».', uk: '«Їдь, Марве. Цьому місцю кінець».', es: '«Vete, Marv. Este sitio se acabó».' }, next: 'go', effect: { flags: { marv_goes: true } } },
               { text: { en: '"Stay. Somebody has to see everything."', ru: '«Останься. Кто-то должен всё видеть».', uk: '«Залишайся. Хтось має все бачити».', es: '«Quédate. Alguien tiene que verlo todo».' }, next: 'stay' },
               ...(s.flags.met_denis ? [
                 { text: { en: '"Denis is alive. Top floor. He asked about you."', ru: '«Денис жив. Верхний этаж. Он спрашивал о тебе».', uk: '«Денис живий. Верхній поверх. Він питав про тебе».', es: '«Denis está vivo. En el último piso. Preguntó por ti».' }, next: 'denis', effect: { flags: { marv_knows_denis: true } } },
               ] : []),
             ] },
        go: { who: 'guest', text: { en: "…Yeah. Yeah. Watch the couch for me. It's seen more than I have.", ru: '…Да. Да. Присмотрите за диваном. Он видел больше, чем я.', uk: '…Так. Так. Наглядайте за диваном. Він бачив більше, ніж я.', es: '…Sí. Sí. Cuídeme el sofá. Ha visto más que yo.' }, next: 'end' },
        stay: { who: 'guest', text: { en: "Ha. Somebody. …Alright. Then I'll see it. Whatever it is tonight, I'll see it.", ru: 'Ха. Кто-то. …Ладно. Тогда увижу. Что бы ни было сегодня, я увижу.', uk: 'Ха. Хтось. …Гаразд. Тоді побачу. Хай що буде сьогодні, я побачу.', es: 'Ja. Alguien. …Está bien. Entonces lo veré. Sea lo que sea esta noche, lo veré.' }, next: 'end' },
        denis: { who: 'guest', text: { en: "…Top floor. All spring, all summer, and me in seven counting ceiling cracks. …Tell him the spare's still under my mat. He'll know which.", ru: '…Верхний этаж. Всю весну, всё лето, а я в седьмом трещины на потолке считал. …Передайте ему, что запасной всё ещё под моим ковриком. Он поймёт, какой.', uk: '…Верхній поверх. Усю весну, все літо, а я в сьомому тріщини на стелі рахував. …Перекажіть йому, що запасний досі під моїм килимком. Він зрозуміє, який.', es: '…El último piso. Toda la primavera, todo el verano, y yo en la siete contando grietas del techo. …Dígale que la de repuesto sigue bajo mi felpudo. Sabrá cuál.' }, next: 'end' },
      }
    },
    {
      name: { en: 'Dana', ru: 'Дана', uk: 'Дана', es: 'Dana' }, voice: { gender: 'f', pitch: 1.05, rate: 1.0 },
      portrait: portrait('#8a3a5a', false, false), start: 'a',
      nodes: {
        a: { who: 'narr', text: (s) => (s.flags.saved_dana && s.flags.dana_stays)
              ? (s.flags.rick_found && !s.flags.dana_safe
                ? { en: "Dana, with the suitcase. She has not slept; Rick's knock is still in the door of room 4 if you look closely. Bus at seven.", ru: 'Дана, с чемоданом. Она не спала; стук Рика до сих пор в двери четвёртого номера, если присмотреться. Автобус в семь.', uk: 'Дана, з валізою. Вона не спала; стукіт Ріка досі в дверях четвертого номера, якщо придивитися. Автобус о сьомій.', es: 'Dana, con la maleta. No ha dormido; si uno se fija, los golpes de Rick siguen en la puerta de la habitación 4. Autobús a las siete.' }
                : { en: "Dana, with the suitcase, again. Yesterday's bus turned back at the river; the road is under water. Coat buttoned wrong, which is the first careless thing you've seen her do. Bus at seven.", ru: 'Дана, с чемоданом, снова. Вчерашний автобус развернули у реки; дорога под водой. Пальто застёгнуто криво; первая небрежность, которую вы за ней видите. Автобус в семь.', uk: 'Дана, з валізою, знову. Вчорашній автобус завернули біля річки; дорога під водою. Пальто застебнуте криво; перша недбалість, яку ви за нею бачите. Автобус о сьомій.', es: 'Dana, con la maleta, otra vez. El autobús de ayer dio la vuelta en el río; la carretera está bajo el agua. El abrigo mal abotonado: el primer descuido que usted le ha visto. Autobús a las siete.' })
              : s.flags.saved_dana
              ? { en: "Room 4 has a salesman in it now. The woman from the first night, who wrote 'thank you' under her name, is a line in the register. You read the line more often than it deserves.", ru: 'В четвёртом номере теперь коммивояжёр. Женщина из первой ночи, написавшая «спасибо» под своим именем, — строчка в книге. Вы перечитываете эту строчку чаще, чем она заслуживает.', uk: 'У четвертому номері тепер комівояжер. Жінка з першої ночі, яка написала «дякую» під своїм ім’ям, — рядок у книзі. Ви перечитуєте цей рядок частіше, ніж він заслуговує.', es: 'En la habitación 4 hay ahora un viajante. La mujer de la primera noche, la que escribió «gracias» bajo su nombre, es una línea en el registro. Usted relee esa línea más de lo que merece.' }
              : { en: "A salesman has the room Rick wanted. The woman from the first night is one line in the register, under his name; you never learned hers. You think about her more than the line deserves.", ru: 'В номере, который хотел Рик, теперь коммивояжёр. Женщина из первой ночи — одна строчка в книге, под его именем; её имени вы так и не узнали. Вы думаете о ней чаще, чем строчка заслуживает.', uk: 'У номері, який хотів Рік, тепер комівояжер. Жінка з першої ночі — один рядок у книзі, під його ім’ям; її імені ви так і не дізналися. Ви думаєте про неї частіше, ніж рядок заслуговує.', es: 'Un viajante tiene la habitación que quería Rick. La mujer de la primera noche es una línea en el registro, bajo el nombre de él; el de ella nunca llegó a saberlo. Piensa en ella más de lo que la línea merece.' },
             next: (s) => ((s.flags.saved_dana && s.flags.dana_stays) ? 'b' : 'end') },
        b: { who: 'guest', text: { en: "Eleven hours on a bus. I have the ticket and the suitcase and nothing else, which is more than I've had in years. …I wanted to say it to someone who'd get it.", ru: 'Одиннадцать часов в автобусе. У меня билет, чемодан и больше ничего, а это больше, чем было у меня годами. …Хотела сказать это тому, кто поймёт.', uk: 'Одинадцять годин в автобусі. У мене квиток, валіза і більше нічого, а це більше, ніж було в мене роками. …Хотіла сказати це тому, хто зрозуміє.', es: 'Once horas de autobús. Tengo el pasaje y la maleta y nada más, que es más de lo que he tenido en años. …Quería decírselo a alguien que lo entendiera.' },
             choices: [
               { text: { en: '"I\'ll walk you to the station when the shift ends."', ru: '«Провожу вас до вокзала, когда сдам смену».', uk: '«Проведу вас до вокзалу, коли здам зміну».', es: '«La acompaño a la estación cuando termine el turno».' }, next: 'walk', effect: { flags: { dana_walk: true } } },
               { text: { en: 'Give her a hundred from the register. "Sal won\'t count it till Monday."', ru: 'Дать ей сто из кассы. «Сэл до понедельника не считает».', uk: 'Дати їй сто з каси. «Сел до понеділка не рахує».', es: 'Darle cien de la caja. «Sal no la cuenta hasta el lunes».' }, next: 'money', effect: { cash: -100, flags: { dana_register: true } } },
               { text: { en: '"Good luck." Nothing else.', ru: '«Удачи». И больше ничего.', uk: '«Щасти». І більше нічого.', es: '«Suerte». Nada más.' }, next: 'luck' },
             ] },
        walk: { who: 'guest', text: { en: "…You don't have to. …Okay. Seven. I'll be the one with the suitcase.", ru: '…Вы не обязаны. …Ладно. В семь. Я буду та, что с чемоданом.', uk: '…Ви не мусите. …Гаразд. О сьомій. Я буду та, що з валізою.', es: '…No tiene por qué. …Está bien. A las siete. Seré la de la maleta.' }, next: 'end' },
        money: { who: 'narr', text: { en: "She takes it slowly, like it's hot. 'I'll send it back. To the desk, not to you. So it's on the record.'", ru: 'Она берёт медленно, будто деньги горячие. «Верну. На стойку, не вам. Чтобы было по правилам».', uk: 'Вона бере повільно, наче гроші гарячі. «Поверну. На стійку, не вам. Щоб було за правилами».', es: 'Lo toma despacio, como si quemara. «Lo devolveré. Al mostrador, no a usted. Para que conste».' }, next: 'end' },
        luck: { who: 'narr', text: { en: "'Luck.' She tries the word out. 'Sure.' She is not bitter about it; she has run out of the energy that takes.", ru: '«Удача». Она пробует слово на вкус. «Ладно». Без обиды; на обиду у неё больше нет сил.', uk: '«Щастя». Вона пробує слово на смак. «Гаразд». Без образи; на образу в неї більше немає сил.', es: '«Suerte». Prueba la palabra. «Claro». No lo dice con amargura; ya no le quedan fuerzas para eso.' }, next: 'end' },
      }
    },
    {
      name: { en: 'Leo', ru: 'Лео', uk: 'Лео', es: 'Leo' }, voice: { gender: 'm', pitch: 1.3, rate: 1.15 },
      portrait: portrait('#6a5a2a', true, false), start: 'a',
      // only a Leo the player actually knows (same rule as night five): a kid turned away on night one is a stranger
      when: (s) => s.flags.leo_friend || s.flags.leo_watch || s.flags.leo_followed || s.flags.kid_couch || (s.flags.kid_room && s.flags.lied_kid),
      nodes: {
        a: { who: 'guest', effect: (s) => (s.flags.leo_money ? { flags: { leo_thanked: true } } : {}), text: (s) => ((t) => (s.flags.leo_money && !s.flags.leo_thanked ? { en: "Somebody left fifty at the shelter. Envelope, my name on it. Nobody writes my name. …I carried it around an hour before I opened it. This hotel's rubbing off on me. " + t.en, ru: "Кто-то оставил в приюте пятьдесят. Конверт, на нём моё имя. Моё имя никто не пишет. …Я час носил его, прежде чем открыть. Ваш отель на меня плохо влияет. " + t.ru, uk: "Хтось залишив у притулку п’ятдесят. Конверт, на ньому моє ім’я. Моє ім’я ніхто не пише. …Я годину носив його, перш ніж відкрити. Ваш готель на мене погано впливає. " + t.uk, es: "Alguien dejó cincuenta en el albergue. Un sobre, con mi nombre. Nadie escribe mi nombre. …Lo llevé encima una hora antes de abrirlo. Este hotel se me está pegando. " + t.es } : t))(s.flags.leo_safe
              ? { en: "Shelter's got a curfew. I'm breaking it. It's the last night on the sheet, right? I counted. …What happens to you?", ru: 'В приюте комендантский час. Я его нарушаю. Это последняя ночь в графике, да? Я считал. …Что с вами будет?', uk: 'У притулку комендантська година. Я її порушую. Це остання ніч у графіку, так? Я рахував. …Що з вами буде?', es: 'En el albergue hay toque de queda. Me lo estoy saltando. Es la última noche del horario, ¿no? Las conté. …¿Qué va a ser de usted?' }
              : s.flags.father_enemy
              ? { en: "My dad's in the car outside. He drove me. He wanted to come in and I said no and he… said okay. First time. …What happens to you tonight?", ru: 'Отец в машине у входа. Он меня привёз. Хотел зайти, я сказал «нет», и он… сказал «ладно». В первый раз. …Что с вами будет сегодня?', uk: 'Батько в машині біля входу. Він мене привіз. Хотів зайти, я сказав «ні», і він… сказав «гаразд». Уперше. …Що з вами буде сьогодні?', es: 'Mi padre está en el coche, ahí fuera. Me trajo él. Quería entrar, le dije que no y él… dijo «bueno». Por primera vez. …¿Qué va a ser de usted esta noche?' }
              : s.flags.leo_followed
              ? { en: "Last night on the sheet. He goes up, not out; I told you. I'll be by the door whether you say so or not. …What happens to you?", ru: 'Последняя ночь в графике. Он идёт наверх, а не на улицу; я говорил. Я буду у двери, скажете вы или нет. …Что с вами будет?', uk: 'Остання ніч у графіку. Він іде нагору, а не на вулицю; я казав. Я буду біля дверей, скажете ви чи ні. …Що з вами буде?', es: 'Última noche del horario. Él sube, no sale; se lo dije. Estaré junto a la puerta, me lo diga o no. …¿Qué va a ser de usted?' }
              : { en: "Two coffees. Last night on the sheet, I saw it through the glass. …What happens to you? Tonight.", ru: 'Два кофе. Последняя ночь в графике, я видел через стекло. …Что с вами будет? Сегодня.', uk: 'Дві кави. Остання ніч у графіку, я бачив крізь скло. …Що з вами буде? Сьогодні.', es: 'Dos cafés. Última noche del horario, lo vi a través del cristal. …¿Qué va a ser de usted? Esta noche.' }),
             choices: (s) => [
               { text: { en: '"Whatever happens, you weren\'t here. Go."', ru: '«Что бы ни случилось, тебя здесь не было. Иди».', uk: '«Хай що станеться, тебе тут не було. Іди».', es: '«Pase lo que pase, tú no estuviste aquí. Vete».' }, next: 'sent', effect: { flags: { leo_sent: true } } },
               { text: { en: '"By the door at three. One last time."', ru: '«У двери в три. Последний раз».', uk: '«Біля дверей о третій. Останній раз».', es: '«Junto a la puerta a las tres. Por última vez».' }, next: 'door', effect: { flags: { leo_door: true } } },
               (s.flags.saved_dana && s.flags.dana_stays)
                 ? { text: { en: 'Fifty from the register. "Seven a.m., bus station. There\'ll be a suitcase."', ru: 'Пятьдесят из кассы. «Семь утра, автовокзал. Там будет чемодан».', uk: 'П’ятдесят із каси. «Сьома ранку, автовокзал. Там буде валіза».', es: 'Cincuenta de la caja. «A las siete de la mañana, en la estación de autobuses. Habrá una maleta».' }, next: 'suitcase', effect: { cash: -50, flags: { leo_suitcase: true } } }
                 : { text: { en: '"Go home, Leo. Whichever one counts."', ru: '«Иди домой, Лео. В тот, который считается».', uk: '«Іди додому, Лео. У той, що рахується».', es: '«Vete a casa, Leo. A la que cuente».' }, next: 'home' },
             ] },
        sent: { who: 'guest', text: { en: "I've been 'not here' my whole life. I'm good at it. …I'll be across the street. Not here.", ru: 'Я всю жизнь «не здесь». У меня хорошо получается. …Буду через дорогу. Не здесь.', uk: 'Я все життя «не тут». У мене добре виходить. …Буду через дорогу. Не тут.', es: 'Toda la vida he sido el que «no estaba aquí». Se me da bien. …Estaré enfrente. No aquí.' }, next: 'end' },
        door: { who: 'guest', text: { en: "Three. Door. …If he looks at me this time, I'm looking back.", ru: 'В три. У двери. …Если он на этот раз посмотрит на меня, я посмотрю в ответ.', uk: 'О третій. Біля дверей. …Якщо він цього разу подивиться на мене, я подивлюся у відповідь.', es: 'A las tres. La puerta. …Si esta vez me mira, le sostengo la mirada.' }, next: 'end' },
        suitcase: { who: 'guest', text: { en: "A suitcase. That's the whole job? …That's the easiest fifty anyone's ever paid me. I'll be early.", ru: 'Чемодан. И это вся работа? …Самые лёгкие пятьдесят, что мне платили. Приду раньше.', uk: 'Валіза. І це вся робота? …Найлегші п’ятдесят, що мені платили. Прийду раніше.', es: 'Una maleta. ¿Ese es todo el trabajo? …Los cincuenta más fáciles que me han pagado nunca. Llegaré antes.' }, next: 'end' },
        home: { who: 'narr', text: { en: "'Whichever one.' He thinks about it longer than the sentence deserves. 'Yeah. Okay.' He leaves the second coffee.", ru: '«В тот, который считается». Он думает над этим дольше, чем фраза заслуживает. «Да. Ладно». Второй кофе оставляет.', uk: '«У той, що рахується». Він думає над цим довше, ніж фраза заслуговує. «Так. Гаразд». Другу каву лишає.', es: '«A la que cuente». Se lo piensa más de lo que la frase merece. «Sí. Está bien». Deja el segundo café.' }, next: 'end' },
      }
    },
    {
      name: { en: 'The woman in grey', ru: 'Женщина в сером', uk: 'Жінка в сірому', es: 'La mujer de gris' }, voice: { gender: 'f', pitch: 0.8, rate: 0.88 },
      portrait: portrait('#5a5a5a', false, true), start: 'a',
      when: (s) => s.flags.offer_grey,
      nodes: {
        a: { who: 'narr', text: { en: 'She comes in without the rain, for once. Over her arm, a grey coat, folded. She lays it on the desk where the envelope used to go.', ru: 'На этот раз она входит без дождя. На руке серое пальто, сложенное. Кладёт его на стойку, туда, где раньше лежал конверт.', uk: 'Цього разу вона заходить без дощу. На руці сіре пальто, складене. Кладе його на стійку, туди, де раніше лежав конверт.', es: 'Por una vez entra sin lluvia. Sobre el brazo, un abrigo gris, doblado. Lo deja en el mostrador, donde antes iba el sobre.' }, next: 'b' },
        b: { who: 'guest', text: (s) => s.flags.becoming_grey
              ? { en: "You said yes. I meant to wear it one more night and then thought: why. Six hotels, six desks. The names are in the lining.", ru: 'Вы сказали «да». Я хотела надеть его ещё на одну ночь, а потом подумала: зачем. Шесть отелей, шесть стоек. Имена зашиты в подкладку.', uk: 'Ви сказали «так». Я хотіла вдягнути його ще на одну ніч, а потім подумала: навіщо. Шість готелів, шість стійок. Імена зашиті в підкладку.', es: 'Usted dijo que sí. Pensaba llevarlo una noche más y luego pensé: para qué. Seis hoteles, seis mostradores. Los nombres están en el forro.' }
              : { en: "You didn't say yes. I'm asking once more, because they don't like it when I retire with no one behind me. Six hotels, six desks. The names are in the lining.", ru: 'Вы не сказали «да». Спрашиваю ещё раз, потому что им не нравится, когда я ухожу и за мной никого нет. Шесть отелей, шесть стоек. Имена зашиты в подкладку.', uk: 'Ви не сказали «так». Питаю ще раз, бо їм не подобається, коли я йду і за мною нікого немає. Шість готелів, шість стійок. Імена зашиті в підкладку.', es: 'Usted no dijo que sí. Se lo pregunto una vez más, porque no les gusta que me retire sin nadie detrás. Seis hoteles, seis mostradores. Los nombres están en el forro.' },
             choices: [
               { text: { en: 'Put on the coat.', ru: 'Надеть пальто.', uk: 'Вдягнути пальто.', es: 'Ponerse el abrigo.' }, next: 'coat', effect: { cash: 500, flags: { final_coat: true, refused_grey: false } } },
               { text: { en: '"No. Retire with no one behind you."', ru: '«Нет. Уходите, и пусть за вами никого не будет».', uk: '«Ні. Ідіть, і хай за вами нікого не буде».', es: '«No. Retírese sin nadie detrás».' }, next: 'no', effect: { flags: { final_coat: false, refused_grey: true } } },
               { text: { en: '"Who took my photograph?"', ru: '«Кто меня сфотографировал?»', uk: '«Хто мене сфотографував?»', es: '«¿Quién me hizo la fotografía?»' }, next: 'who' },
             ] },
        who: { who: 'guest', text: { en: "I did. From the door, the first night. You were looking at the register; nobody looks at the door. It's a good photograph. You look like someone who hasn't decided yet.", ru: 'Я. От двери, в первую ночь. Вы смотрели в книгу; на дверь никто не смотрит. Хорошая фотография. Вы на ней похожи на человека, который ещё не решил.', uk: 'Я. Від дверей, першої ночі. Ви дивилися в книгу; на двері ніхто не дивиться. Гарна фотографія. Ви на ній схожі на людину, яка ще не вирішила.', es: 'Yo. Desde la puerta, la primera noche. Usted miraba el registro; nadie mira la puerta. Es una buena fotografía. Parece alguien que todavía no ha decidido.' },
               choices: [
                 { text: { en: 'Put on the coat.', ru: 'Надеть пальто.', uk: 'Вдягнути пальто.', es: 'Ponerse el abrigo.' }, next: 'coat', effect: { cash: 500, flags: { final_coat: true, refused_grey: false } } },
                 { text: { en: '"No. Retire with no one behind you."', ru: '«Нет. Уходите, и пусть за вами никого не будет».', uk: '«Ні. Ідіть, і хай за вами нікого не буде».', es: '«No. Retírese sin nadie detrás».' }, next: 'no', effect: { flags: { final_coat: false, refused_grey: true } } },
               ] },
        coat: { who: 'guest', text: { en: "It fits. It always fits. First desk is Tuesday; the address is in the pocket with the money. Leave the envelope. Take the photograph yourself.", ru: 'Сидит. Оно всегда сидит. Первая стойка во вторник; адрес в кармане, вместе с деньгами. Конверт оставьте. Фотографию сделайте сами.', uk: 'Сидить. Воно завжди сидить. Перша стійка у вівторок; адреса в кишені, разом із грошима. Конверт залиште. Фотографію зробіть самі.', es: 'Le queda bien. Siempre queda bien. El primer mostrador es el martes; la dirección está en el bolsillo, con el dinero. Deje el sobre. La fotografía hágala usted.' }, next: 'end' },
        no: { who: 'guest', text: { en: "…Then I was never here, and neither, as far as they're concerned, were you. It's the kindest thing I have. …He'll still come at three.", ru: '…Тогда меня здесь не было, и вас, с их точки зрения, тоже. Это самое доброе, что у меня есть. …Он всё равно придёт в три.', uk: '…Тоді мене тут не було, і вас, з їхнього погляду, теж. Це найдобріше, що в мене є. …Він усе одно прийде о третій.', es: '…Entonces yo nunca estuve aquí, y usted, para ellos, tampoco. Es lo más amable que tengo. …Él vendrá igual a las tres.' }, next: 'end' },
      }
    },
    {
      time: '03:00', name: { en: 'The man in the good coat', ru: 'Мужчина в хорошем пальто', uk: 'Чоловік у гарному пальті', es: 'El hombre del abrigo bueno' }, voice: { gender: 'm', pitch: 0.65, rate: 0.9 },
      portrait: portrait('#1e1e2e', true, false), start: 'a',
      nodes: {
        a: { who: 'narr', text: (s) => s.flags.leo_door
              ? { en: '03:00. Leo, by the door. The man comes in and looks at Leo first, for exactly as long as it takes to learn a face. Then at you.', ru: '03:00. Лео у двери. Мужчина входит и сначала смотрит на Лео, ровно столько, сколько нужно, чтобы запомнить лицо. Потом на вас.', uk: '03:00. Лео біля дверей. Чоловік заходить і спершу дивиться на Лео, рівно стільки, скільки треба, щоб запам’ятати обличчя. Потім на вас.', es: '03:00. Leo, junto a la puerta. El hombre entra y mira primero a Leo, justo lo que se tarda en aprenderse una cara. Luego a usted.' }
              : s.flags.leo_sent
              ? { en: '03:00. Across the street, in the bus shelter, a hood turns toward the window. The door opens without a sound. Him.', ru: '03:00. Через дорогу, на автобусной остановке, капюшон поворачивается к окну. Дверь открывается беззвучно. Он.', uk: '03:00. Через дорогу, на автобусній зупинці, каптур повертається до вікна. Двері відчиняються беззвучно. Він.', es: '03:00. Enfrente, en la parada del autobús, una capucha se vuelve hacia la ventana. La puerta se abre sin ruido. Él.' }
              : s.flags.final_coat
              ? { en: "03:00. He sees the coat before he sees you. He smiles. It is the first time, and you'd rather it wasn't.", ru: '03:00. Он видит пальто раньше, чем вас. Улыбается. В первый раз, и лучше бы не улыбался.', uk: '03:00. Він бачить пальто раніше, ніж вас. Усміхається. Уперше, і краще б не всміхався.', es: '03:00. Ve el abrigo antes que a usted. Sonríe. Es la primera vez, y preferiría que no lo fuera.' }
              : { en: '03:00. No phone tonight. Just the door, and him in it, not shaking the cold off, looking at you.', ru: '03:00. Сегодня без телефона. Просто дверь, и в ней он: не стряхивает холод, смотрит на вас.', uk: '03:00. Сьогодні без телефону. Просто двері, і в них він: не струшує холод, дивиться на вас.', es: '03:00. Esta noche no hay teléfono. Solo la puerta, y él en ella, sin sacudirse el frío, {mirándolo|mirándola}.' },
             next: 'b' },
        b: { who: 'guest', text: (s) => s.flags.final_coat
              ? { en: "Grey suits you. She said it would. Then there's nothing to discuss except Friday, and Friday discusses itself.", ru: 'Серое вам идёт. Она говорила, что пойдёт. Значит, обсуждать нечего, кроме пятницы, а пятница обсуждает себя сама.', uk: 'Сіре вам пасує. Вона казала, що пасуватиме. Отже, обговорювати нічого, крім п’ятниці, а п’ятниця обговорює себе сама.', es: 'El gris le sienta bien. Ella dijo que le sentaría. Entonces no hay nada que hablar salvo el viernes, y el viernes se habla solo.' }
              : (s.flags.went_up || s.flags.met_denis)
              ? { en: "You've been upstairs. Denis told me; Denis tells me everything, eventually. So you know what the room is. Tonight I'm asking what you are.", ru: 'Вы были наверху. Денис рассказал; Денис рано или поздно рассказывает мне всё. Значит, вы знаете, что такое эта комната. Сегодня я спрашиваю, что такое вы.', uk: 'Ви були нагорі. Денис розповів; Денис рано чи пізно розповідає мені все. Отже, ви знаєте, що таке ця кімната. Сьогодні я питаю, що таке ви.', es: 'Ha estado arriba. Me lo dijo Denis; Denis me lo cuenta todo, tarde o temprano. Así que sabe lo que es la habitación. Esta noche le pregunto qué es usted.' }
              : s.flags.stayed_down
              ? { en: "You had a key and kept it in a drawer. Denis would have gone up on night one. …I'm not here for an envelope. I'm asking what you are.", ru: 'У вас был ключ, и вы держали его в ящике. Денис поднялся бы в первую же ночь. …Я не за конвертом. Я спрашиваю, что такое вы.', uk: 'У вас був ключ, і ви тримали його в шухляді. Денис піднявся б першої ж ночі. …Я не по конверт. Я питаю, що таке ви.', es: 'Tenía una llave y la guardó en un cajón. Denis habría subido la primera noche. …No vengo por un sobre. Le pregunto qué es usted.' }
              : s.flags.man_side
              ? { en: "You picked my side once. I don't forget that; I don't reward it either. Tonight I'm asking where you'd like to stand.", ru: 'Однажды вы выбрали мою сторону. Я этого не забываю; но и не награждаю. Сегодня я спрашиваю, где вы хотите стоять.', uk: 'Одного разу ви обрали мій бік. Я цього не забуваю; але й не винагороджую. Сьогодні я питаю, де ви хочете стояти.', es: 'Una vez eligió mi bando. No lo olvido; tampoco lo premio. Esta noche le pregunto dónde quiere estar.' }
              : s.flags.key_pocket
              ? { en: "You have it on you. I can tell; people stand differently with a key in their pocket. Denis stood like that for a week. Tonight I'm asking.", ru: 'Он у вас с собой. Я вижу; люди стоят иначе, когда в кармане ключ. Денис так стоял неделю. Сегодня я спрашиваю.', uk: 'Він у вас із собою. Я бачу; люди стоять інакше, коли в кишені ключ. Денис так стояв тиждень. Сьогодні я питаю.', es: 'La lleva encima. Se nota; la gente se planta distinto con una llave en el bolsillo. Denis estuvo así una semana. Esta noche pregunto yo.' }
              : (s.flags.marked || s.flags.threatened)
              ? { en: "Six nights. I've watched five of them. Denis lasted eleven before I asked him. I'm asking you tonight.", ru: 'Шесть ночей. Пять из них я смотрел. Денис продержался одиннадцать, прежде чем я спросил. Вас я спрашиваю сегодня.', uk: 'Шість ночей. П’ять із них я дивився. Денис протримався одинадцять, перш ніж я спитав. Вас я питаю сьогодні.', es: 'Seis noches. He mirado cinco. Denis aguantó once antes de que se lo preguntara. A usted se lo pregunto esta noche.' }
              : { en: "Six nights. Denis lasted eleven before I asked. I'm not here for an envelope. I'm here to ask what you want.", ru: 'Шесть ночей. Денис продержался одиннадцать, прежде чем я спросил. Я не за конвертом. Я — спросить, чего вы хотите.', uk: 'Шість ночей. Денис протримався одинадцять, перш ніж я спитав. Я не по конверт. Я — спитати, чого ви хочете.', es: 'Seis noches. Denis aguantó once antes de que se lo preguntara. No vengo por un sobre. Vengo a preguntarle qué quiere.' },
             next: 'c' },
        c: { who: 'guest', text: { en: "The room upstairs needs a keeper. The desk needs a clerk who knows. The city needs a woman in grey. Pick one. Or pick none, and I'll pick for you.", ru: 'Комнате наверху нужен хранитель. Стойке нужен портье, который знает. Городу нужна женщина в сером. Выберите одно. Или не выбирайте, и я выберу за вас.', uk: 'Кімнаті нагорі потрібен хранитель. Стійці потрібен портьє, який знає. Місту потрібна жінка в сірому. Оберіть одне. Або не обирайте, і я оберу за вас.', es: 'La habitación de arriba necesita un guardián. El mostrador necesita un recepcionista que sepa. La ciudad necesita una mujer de gris. Elija una cosa. O ninguna, y elegiré yo por usted.' },
             choices: (s) => s.flags.final_coat
              ? [
                  { text: { en: '"I already picked. Grey."', ru: '«Выбор сделан. Серое».', uk: '«Вибір зроблено. Сіре».', es: '«Ya elegí. El gris».' }, next: 'grey' },
                  { text: { en: '"It ends tonight. All of it."', ru: '«Сегодня всё закончится. Всё».', uk: '«Сьогодні все скінчиться. Усе».', es: '«Esto se acaba esta noche. Todo».' }, next: 'ends', effect: { trouble: 2, flags: { defied_man: true } } },
                ]
              : [
                  { text: { en: '"The room. I\'ll go up."', ru: '«Комната. Я поднимусь».', uk: '«Кімната. Я піднімуся».', es: '«La habitación. Subiré».' }, next: 'up', effect: { flags: { final_up: true } } },
                  ...(s.flags.has_key ? [
                    { text: { en: 'Put the key on the desk. "Take it back."', ru: 'Положить ключ на стойку. «Заберите».', uk: 'Покласти ключ на стійку. «Заберіть».', es: 'Dejar la llave en el mostrador. «Llévesela».' }, next: 'back', effect: { flags: { returned_key: true } } },
                  ] : []),
                  { text: { en: '"There is no room twelve."', ru: '«Двенадцатого номера нет».', uk: '«Дванадцятого номера немає».', es: '«No hay habitación doce».' }, next: 'silent', effect: { cash: 300, flags: { silent_man: true } } },
                  { text: { en: '"It ends tonight. All of it."', ru: '«Сегодня всё закончится. Всё».', uk: '«Сьогодні все скінчиться. Усе».', es: '«Esto se acaba esta noche. Todo».' }, next: 'ends', effect: { trouble: 2, flags: { defied_man: true } } },
                ] },
        up: { who: 'guest', text: { en: "Denis will be glad. He won't say so; he's forgotten how. …The door at the top is open. It has been open all week.", ru: 'Денис будет рад. Не скажет; он разучился. …Дверь наверху открыта. Всю неделю открыта.', uk: 'Денис буде радий. Не скаже; він розучився. …Двері нагорі відчинені. Весь тиждень відчинені.', es: 'Denis se alegrará. No lo dirá; se le ha olvidado cómo. …La puerta de arriba está abierta. Lleva toda la semana abierta.' }, next: 'up2' },
        up2: { who: 'narr', text: { en: 'He holds the stair door for you. He does not follow. He has never had to.', ru: 'Он придерживает для вас дверь на лестницу. Сам не идёт. Ему никогда не приходилось.', uk: 'Він притримує для вас двері на сходи. Сам не йде. Йому ніколи не доводилося.', es: 'Le sostiene la puerta de la escalera. No {lo|la} sigue. Nunca le ha hecho falta.' }, next: 'end' },
        back: { who: 'guest', text: { en: "…Nobody has ever given one back. I don't have a sentence for that.", ru: '…Никто ещё не возвращал. У меня нет фразы на этот случай.', uk: '…Ніхто ще не повертав. У мене немає фрази на цей випадок.', es: '…Nadie había devuelto nunca una. No tengo frase para eso.' }, next: 'back2' },
        back2: { who: 'narr', text: { en: 'He leaves the key where it is. He leaves. The key stays on the desk like a coin nobody will pick up.', ru: 'Ключ он не берёт. Уходит. Ключ лежит на стойке, как монета, которую никто не поднимет.', uk: 'Ключ він не бере. Іде. Ключ лежить на стійці, як монета, яку ніхто не підніме.', es: 'Deja la llave donde está. Se va. La llave se queda en el mostrador como una moneda que nadie va a recoger.' }, next: 'end' },
        silent: { who: 'guest', text: { en: "Word for word. …That's the desk, then. Good. It's the only job in this building that ends in a pension.", ru: 'Слово в слово. …Значит, стойка. Хорошо. Это единственная работа в этом здании, которая заканчивается пенсией.', uk: 'Слово в слово. …Отже, стійка. Добре. Це єдина робота в цій будівлі, яка закінчується пенсією.', es: 'Palabra por palabra. …Entonces, el mostrador. Bien. Es el único trabajo de este edificio que acaba en jubilación.' }, next: 'silent2' },
        silent2: { who: 'narr', text: { en: "Three hundred, in fifties. He doesn't count it. Counting is for people who might be short.", ru: 'Триста, полтинниками. Он не считает. Считают те, у кого может не хватить.', uk: 'Триста, п’ятдесятками. Він не рахує. Рахують ті, в кого може не вистачити.', es: 'Trescientos, en billetes de cincuenta. No los cuenta. Contar es para quien puede quedarse corto.' }, next: 'end' },
        ends: { who: 'guest', text: { en: "Denis said no once. You've made a habit of it; that's the record. …Nothing ends at night, clerk. Things end on paper, in daylight, with someone like Reyes holding the pen.", ru: 'Денис сказал «нет» один раз. У вас это вошло в привычку; это рекорд. …Ночью ничего не заканчивается, портье. Всё заканчивается на бумаге, при свете дня, когда ручку держит кто-то вроде Рейес.', uk: 'Денис сказав «ні» один раз. У вас це стало звичкою; це рекорд. …Уночі ніщо не закінчується, портьє. Усе закінчується на папері, при денному світлі, коли ручку тримає хтось на кшталт Реєс.', es: 'Denis dijo que no una vez. Usted lo ha convertido en costumbre; eso es todo un récord. …De noche no se acaba nada, recepcionista. Las cosas se acaban en papel, a la luz del día, con alguien como Reyes sosteniendo el bolígrafo.' }, next: 'end' },
        grey: { who: 'guest', text: { en: "So you did. Tuesday, then. Don't open the envelopes; she never did, and she's the only one of us retiring.", ru: 'Сделан. Значит, вторник. Конверты не открывайте; она не открывала, и она единственная из нас уходит на пенсию.', uk: 'Зроблено. Отже, вівторок. Конвертів не відкривайте; вона не відкривала, і вона єдина з нас іде на пенсію.', es: 'Eso veo. Entonces, el martes. No abra los sobres; ella nunca los abrió, y es la única de nosotros que se jubila.' }, next: 'end' },
      }
    },
    {
      time: '04:00', name: { en: 'Denis', ru: 'Денис', uk: 'Денис', es: 'Denis' }, voice: { gender: 'm', pitch: 0.9, rate: 0.85 },
      portrait: portrait('#6a6a7a', false, false), start: 'a',
      when: (s) => s.flags.denis_ally || s.flags.denis_stays || s.flags.final_up,
      nodes: {
        a: { who: 'narr', text: (s) => s.flags.final_up
              ? { en: 'Room twelve is not a room. It is a corridor with a bed at the end and photographs from floor to ceiling. Denis is at the window. He has been expecting you since spring.', ru: 'Двенадцатый номер — не номер. Это коридор с кроватью в конце и фотографиями от пола до потолка. Денис у окна. Он ждёт вас с весны.', uk: 'Дванадцятий номер — не номер. Це коридор із ліжком у кінці й фотографіями від підлоги до стелі. Денис біля вікна. Він чекає на вас із весни.', es: 'La habitación doce no es una habitación. Es un pasillo con una cama al fondo y fotografías del suelo al techo. Denis está junto a la ventana. {Lo|La} espera desde la primavera.' }
              : s.flags.marv_knows_denis
              ? { en: "04:00. The stairs creak in the wrong direction: somebody coming down. Denis, with Marv's spare in his hand; the mat outside seven is turned back. He looks at the lamp like it's a person.", ru: '04:00. Лестница скрипит не в ту сторону: кто-то спускается. Денис, с запасным ключом Марва в руке; коврик у седьмого отогнут. Он смотрит на лампу, как на человека.', uk: '04:00. Сходи скриплять не в той бік: хтось спускається. Денис, із запасним ключем Марва в руці; килимок біля сьомого відгорнутий. Він дивиться на лампу, як на людину.', es: '04:00. La escalera cruje en la dirección equivocada: alguien baja. Denis, con la llave de repuesto de Marv en la mano; el felpudo de la siete está levantado. Mira la lámpara como si fuera una persona.' }
              : { en: "04:00. The stairs creak in the wrong direction: somebody coming down. Denis. He has not been below the top floor since spring. He looks at the lamp like it's a person.", ru: '04:00. Лестница скрипит не в ту сторону: кто-то спускается. Денис. Он не спускался ниже верхнего этажа с весны. Он смотрит на лампу, как на человека.', uk: '04:00. Сходи скриплять не в той бік: хтось спускається. Денис. Він не спускався нижче верхнього поверху з весни. Він дивиться на лампу, як на людину.', es: '04:00. La escalera cruje en la dirección equivocada: alguien baja. Denis. No ha bajado del último piso desde la primavera. Mira la lámpara como si fuera una persona.' },
             next: 'b' },
        b: { who: 'guest', text: (s) => s.flags.final_up
              ? { en: "You came up. …Okay. The rules are on the back of the door; don't read them tonight. Tonight just tell me what the lamp looks like from the other side of the desk.", ru: 'Вы поднялись. …Ладно. Правила на обратной стороне двери; сегодня не читайте. Сегодня просто скажите, как выглядит лампа с той стороны стойки.', uk: 'Ви піднялися. …Гаразд. Правила на звороті дверей; сьогодні не читайте. Сьогодні просто скажіть, яка на вигляд лампа з того боку стійки.', es: 'Ha subido. …Bien. Las reglas están detrás de la puerta; no las lea esta noche. Esta noche solo dígame cómo se ve la lámpara desde el otro lado del mostrador.' }
              : s.flags.denis_ally
              ? (s.flags.took_photos
                ? { en: "You still have the photographs? Then it's tonight. He's at the diner till five. Reyes, or a reporter I used to know at the Herald. Choose fast; I'm out of practice at stairs.", ru: 'Фотографии ещё у вас? Тогда сегодня. Он в закусочной до пяти. Рейес или журналистка, которую я знал в «Геральде». Решайте быстро; я отвык от лестниц.', uk: 'Фотографії ще у вас? Тоді сьогодні. Він у закусочній до п’ятої. Реєс або репортерка, яку я знав у «Гералді». Вирішуйте швидко; я відвик від сходів.', es: '¿Todavía tiene las fotografías? Entonces es esta noche. Él está en la cafetería hasta las cinco. Reyes, o una periodista que conocí en el Herald. Decida rápido; ya no tengo práctica con las escaleras.' }
                : { en: "I took them down. Every photograph. Seventeen clerks, in a bag. He's at the diner till five. Reyes, or a reporter I used to know at the Herald. Choose fast; I'm out of practice at stairs.", ru: 'Я снял их. Все фотографии. Семнадцать портье, в сумке. Он в закусочной до пяти. Рейес или журналистка, которую я знал в «Геральде». Решайте быстро; я отвык от лестниц.', uk: 'Я зняв їх. Усі фотографії. Сімнадцять портьє, у сумці. Він у закусочній до п’ятої. Реєс або репортерка, яку я знав у «Гералді». Вирішуйте швидко; я відвик від сходів.', es: 'Las descolgué. Todas las fotografías. Diecisiete recepcionistas, en una bolsa. Él está en la cafetería hasta las cinco. Reyes, o una periodista que conocí en el Herald. Decida rápido; ya no tengo práctica con las escaleras.' })
              : { en: "I'm not leaving. I'm saying that first so you stop planning. I came down because Friday is over and I wanted to see the lamp from this side. Once.", ru: 'Я не уйду. Говорю это первым делом, чтобы вы перестали строить планы. Спустился, потому что пятница прошла, и я хотел увидеть лампу с этой стороны. Один раз.', uk: 'Я не піду. Кажу це першим, щоб ви перестали будувати плани. Спустився, бо п’ятниця минула, і я хотів побачити лампу з цього боку. Один раз.', es: 'No me voy. Se lo digo lo primero para que deje de hacer planes. He bajado porque el viernes ya pasó y quería ver la lámpara desde este lado. Una vez.' },
             choices: (s) => s.flags.final_up
              ? [
                  { text: { en: '"Take the desk. It\'s yours. It always was."', ru: '«Берите стойку. Она ваша. Всегда была».', uk: '«Беріть стійку. Вона ваша. Завжди була».', es: '«Quédese con el mostrador. Es suyo. Siempre lo fue».' }, next: 'handover' },
                  { text: { en: '"I can\'t. I\'m going back down."', ru: '«Не могу. Я спускаюсь обратно».', uk: '«Не можу. Я спускаюся назад».', es: '«No puedo. Vuelvo abajo».' }, next: 'backout', effect: { flags: { final_up: false, backed_out: true } } },
                ]
              : s.flags.denis_ally
              ? [
                  { text: { en: '"The Herald. Not Reyes."', ru: '«Геральд». Не Рейес.', uk: '«Гералд». Не Реєс.', es: '«El Herald. Reyes no».' }, next: 'herald', effect: { flags: { final_fire: true } } },
                  { text: { en: '"Reyes. She\'s what we\'ve got."', ru: '«Рейес. Другой у нас нет».', uk: '«Реєс. Іншої в нас немає».', es: '«Reyes. Es lo que tenemos».' }, next: 'reyesch', effect: { flags: { denis_reyes: true } } },
                  { text: { en: '"Not tonight. Take them back up. Keep them safe."', ru: '«Не сегодня. Унесите обратно наверх. Сберегите».', uk: '«Не сьогодні. Віднесіть назад нагору. Збережіть».', es: '«Esta noche no. Súbalas otra vez. Guárdelas bien».' }, next: 'wait', effect: { flags: { denis_wait: true } } },
                ]
              : [
                  { text: { en: '"Then swap with me. One night. I go up, you sit at the lamp."', ru: '«Тогда поменяемся. На одну ночь. Я наверх, вы к лампе».', uk: '«Тоді поміняємося. На одну ніч. Я нагору, ви до лампи».', es: '«Entonces cambiemos. Una noche. Yo subo, usted se sienta junto a la lámpara».' }, next: 'swap', effect: { flags: { final_up: true } } },
                  { text: { en: '"Stay, then. I\'ll bring coffee up at five."', ru: '«Тогда оставайтесь. Я принесу кофе наверх в пять».', uk: '«Тоді лишайтеся. Я принесу каву нагору о п’ятій».', es: '«Entonces quédese. Le subo café a las cinco».' }, next: 'coffee' },
                  { text: { en: '"Who\'s up there with you?"', ru: '«Кто там с вами?»', uk: '«Хто там із вами?»', es: '«¿Quién está ahí arriba con usted?»' }, next: 'who' },
                ] },
        handover: { who: 'narr', text: { en: 'He goes down the stairs slowly, like someone who has forgotten how they work. From the top, you hear the lamp click on. Then the phone, which does not ring.', ru: 'Он спускается медленно, как человек, забывший, как работают лестницы. Сверху слышно, как щёлкает лампа. Потом телефон, который не звонит.', uk: 'Він спускається повільно, як людина, що забула, як працюють сходи. Згори чути, як клацає лампа. Потім телефон, який не дзвонить.', es: 'Baja la escalera despacio, como quien ha olvidado cómo funciona. Desde arriba oye el clic de la lámpara al encenderse. Luego el teléfono, que no suena.' }, next: 'end' },
        backout: { who: 'guest', text: { en: "Nobody comes back down. …You'd be the first. Go, then. Go before he counts to whatever he counts to.", ru: 'Обратно ещё никто не спускался. …Будет прецедент. Ну так идите. Идите, пока он не досчитал до того, до чего считает.', uk: 'Назад ще ніхто не спускався. …Буде прецедент. То йдіть. Ідіть, поки він не дорахував до того, до чого рахує.', es: 'Nadie vuelve a bajar. …Sería {el primero|la primera}. Váyase, entonces. Váyase antes de que él cuente hasta lo que sea que cuente.' }, next: 'end' },
        herald: { who: 'narr', text: { en: "He writes a name and a number on the back of a photograph of himself. 'She'll want the diner, six a.m. Wear a different coat.'", ru: 'Он пишет имя и номер на обороте собственной фотографии. «Она захочет в закусочной, в шесть утра. Наденьте другое пальто».', uk: 'Він пише ім’я і номер на звороті власної фотографії. «Вона захоче в закусочній, о шостій ранку. Вдягніть інше пальто».', es: 'Escribe un nombre y un número en el reverso de una fotografía suya. «Querrá quedar en la cafetería, a las seis de la mañana. Póngase otro abrigo».' }, next: 'end' },
        reyesch: { who: 'guest', text: { en: "She's what he's got. …Fine. But I'm not in the room when you hand them over. I've been in enough rooms.", ru: 'Другой нет у него. …Ладно. Но когда будете отдавать, меня в комнате не будет. Комнат с меня хватит.', uk: 'Іншої немає в нього. …Гаразд. Але коли віддаватимете, мене в кімнаті не буде. Кімнат із мене досить.', es: 'Es lo que tiene él. …Bien. Pero cuando las entregue, yo no estaré en la habitación. Ya he estado en bastantes habitaciones.' }, next: 'end' },
        wait: { who: 'guest', text: { en: "There's no such thing as 'not tonight' up there. …Okay.", ru: 'Наверху не бывает «не сегодня». …Ладно.', uk: 'Нагорі не буває «не сьогодні». …Гаразд.', es: 'Ahí arriba no existe «esta noche no». …Está bien.' }, next: 'wait2' },
        wait2: { who: 'narr', text: { en: 'He goes back up anyway. He takes the photographs with him. The stairs creak in the right direction.', ru: 'Он всё равно поднимается. Фотографии забирает с собой. Лестница скрипит в правильную сторону.', uk: 'Він усе одно піднімається. Фотографії забирає з собою. Сходи скриплять у правильний бік.', es: 'Vuelve a subir de todos modos. Se lleva las fotografías. La escalera cruje en la dirección correcta.' }, next: 'end' },
        swap: { who: 'narr', text: { en: "He looks at the lamp for a long time. 'One night,' he says, and you both know what one night is worth in this building.", ru: 'Он долго смотрит на лампу. «Одну ночь», говорит он, и вы оба знаете, чего стоит одна ночь в этом здании.', uk: 'Він довго дивиться на лампу. «Одну ніч», каже він, і ви обоє знаєте, чого варта одна ніч у цій будівлі.', es: 'Mira la lámpara largo rato. «Una noche», dice, y los dos saben lo que vale una noche en este edificio.' }, next: 'end' },
        coffee: { who: 'guest', text: { en: "Black. …The last one who brought coffee up is on the wall now. Bring it anyway.", ru: 'Чёрный. …Последний, кто приносил кофе наверх, теперь на стене. Всё равно принесите.', uk: 'Чорну. …Останній, хто приносив каву нагору, тепер на стіні. Все одно принесіть.', es: 'Solo. …El último que me subió café está ahora en la pared. Súbalo igual.' }, next: 'end' },
        who: { who: 'guest', text: { en: "Tonight, nobody. Tomorrow, a girl from the bus station who thinks it's a hostel. That's why I stay. Somebody should be kind about it.", ru: 'Сегодня никого. Завтра девушка с автовокзала, которая думает, что это хостел. Поэтому я остаюсь. Кто-то должен быть добрым хотя бы в этом.', uk: 'Сьогодні нікого. Завтра дівчина з автовокзалу, яка думає, що це хостел. Тому я лишаюся. Хтось має бути добрим хоча б у цьому.', es: 'Esta noche, nadie. Mañana, una chica de la estación de autobuses que cree que esto es un albergue. Por eso me quedo. Alguien debería hacerlo con amabilidad.' },
               choices: [
                 { text: { en: '"Then swap with me. One night. I go up, you sit at the lamp."', ru: '«Тогда поменяемся. На одну ночь. Я наверх, вы к лампе».', uk: '«Тоді поміняємося. На одну ніч. Я нагору, ви до лампи».', es: '«Entonces cambiemos. Una noche. Yo subo, usted se sienta junto a la lámpara».' }, next: 'swap', effect: { flags: { final_up: true } } },
                 { text: { en: '"Stay, then. I\'ll bring coffee up at five."', ru: '«Тогда оставайтесь. Я принесу кофе наверх в пять».', uk: '«Тоді лишайтеся. Я принесу каву нагору о п’ятій».', es: '«Entonces quédese. Le subo café a las cinco».' }, next: 'coffee' },
               ] },
      }
    },
    {
      time: '05:00', name: { en: 'Officer Reyes', ru: 'Офицер Рейес', uk: 'Офіцер Реєс', es: 'Agente Reyes' }, voice: { gender: 'f', pitch: 0.95, rate: 1.0 },
      portrait: portrait('#2a3a6a', true, false), start: 'a',
      nodes: {
        a: { who: 'narr', text: (s) => s.flags.final_up
              ? { en: '05:00. Reyes. Denis is behind the desk in your cardigan; you stand beside it with the twelve key on the counter between you. She looks at the key, at Denis, at you. In that order.', ru: '05:00. Рейес. Денис за стойкой в вашей кофте; вы стоите рядом, ключ с биркой 12 лежит на стойке между вами. Она смотрит на ключ, на Дениса, на вас. В этом порядке.', uk: '05:00. Реєс. Денис за стійкою у вашій кофті; ви стоїте поруч, ключ із биркою 12 лежить на стійці між вами. Вона дивиться на ключ, на Дениса, на вас. Саме в такому порядку.', es: '05:00. Reyes. Denis está tras el mostrador con su chaqueta de punto, la de usted; usted está de pie al lado, con la llave doce sobre el mostrador entre los dos. Ella mira la llave, a Denis, a usted. En ese orden.' }
              : s.flags.final_coat
              ? { en: '05:00. Reyes stops in the doorway. She knows the coat. She knew the last one.', ru: '05:00. Рейес останавливается в дверях. Она знает это пальто. Знала и предыдущее.', uk: '05:00. Реєс зупиняється у дверях. Вона знає це пальто. Знала й попереднє.', es: '05:00. Reyes se detiene en la puerta. Conoce el abrigo. Conocía el anterior.' }
              : s.flags.final_fire
              ? { en: '05:00. Reyes. She has been up all night too, and she looks at the stairs before she looks at you.', ru: '05:00. Рейес. Она тоже не спала всю ночь и смотрит на лестницу раньше, чем на вас.', uk: '05:00. Реєс. Вона теж не спала всю ніч і дивиться на сходи раніше, ніж на вас.', es: '05:00. Reyes. Ella tampoco ha dormido en toda la noche, y mira la escalera antes que a usted.' }
              : s.flags.backed_out
              ? { en: '05:00. Reyes. Your legs still remember the stairs, both directions. She looks at the stairs before she looks at you, and then at you for a long time.', ru: '05:00. Рейес. Ноги ещё помнят лестницу, в обе стороны. Она смотрит на лестницу раньше, чем на вас, а потом на вас — долго.', uk: '05:00. Реєс. Ноги ще пам’ятають сходи, в обидва боки. Вона дивиться на сходи раніше, ніж на вас, а потім на вас — довго.', es: '05:00. Reyes. Sus piernas aún recuerdan la escalera, en los dos sentidos. Ella mira la escalera antes que a usted, y luego a usted, largo rato.' }
              : { en: '05:00. Reyes. She looks worse than the first night, and on the first night she was wet through.', ru: '05:00. Рейес. Выглядит хуже, чем в первую ночь, а в первую ночь она промокла насквозь.', uk: '05:00. Реєс. Вигляд гірший, ніж першої ночі, а першої ночі вона промокла наскрізь.', es: '05:00. Reyes. Tiene peor aspecto que la primera noche, y la primera noche estaba calada hasta los huesos.' },
             next: 'b' },
        b: { who: 'guest', text: (s) => s.flags.final_up
              ? { en: "So that's how it goes. The keeper takes the desk, the clerk takes the room. …I'll write 'no room twelve' in the report. I've written it before; my hand knows the way.", ru: 'Значит, вот как это бывает. Хранитель берёт стойку, портье берёт комнату. …В отчёте напишу: «двенадцатого номера нет». Я это уже писала; рука сама знает дорогу.', uk: 'Отже, ось як це буває. Хранитель бере стійку, портьє бере кімнату. …У звіті напишу: «дванадцятого номера немає». Я це вже писала; рука сама знає дорогу.', es: 'Así que así funciona. El guardián se queda el mostrador, {el|la} recepcionista se queda la habitación. …En el informe pondré «no hay habitación doce». Ya lo he escrito antes; la mano se sabe el camino.' }
              : s.flags.final_coat
              ? { en: "Grey. …I asked her once what happens to the old coat. She said: it gets a badge. So. We'll be seeing each other.", ru: 'Серое. …Я как-то спросила её, что бывает со старым пальто. Она сказала: ему выдают значок. Так что. Мы ещё увидимся.', uk: 'Сіре. …Я якось спитала її, що буває зі старим пальтом. Вона сказала: йому видають жетон. Тож. Ми ще побачимося.', es: 'Gris. …Una vez le pregunté qué pasa con el abrigo viejo. Me dijo: le dan una placa. Así que ya ve. Nos seguiremos viendo.' }
              : s.flags.final_fire
              ? { en: "Denis came down. Don't bother; the stairs told me. Whatever you've got is mine, not a newspaper's. A newspaper can't protect you.", ru: 'Денис спускался. Не трудитесь; лестница мне рассказала. Всё, что у вас есть, моё, а не газеты. Газета вас не защитит.', uk: 'Денис спускався. Не старайтеся; сходи мені розповіли. Усе, що у вас є, моє, а не газети. Газета вас не захистить.', es: 'Denis bajó. No se moleste; me lo dijo la escalera. Lo que tenga es mío, no de un periódico. Un periódico no puede {protegerlo|protegerla}.' }
              : s.flags.reyes_deal
              ? { en: "Car's outside. The deal stands: a statement, immunity, a city with a different river. It's now, or it's never, and never is a long shift.", ru: 'Машина у входа. Сделка в силе: показания, неприкосновенность, город с другой рекой. Сейчас или никогда, а «никогда» — длинная смена.', uk: 'Машина біля входу. Угода чинна: свідчення, недоторканність, місто з іншою річкою. Зараз або ніколи, а «ніколи» — довга зміна.', es: 'El coche está fuera. El trato sigue en pie: una declaración, inmunidad, una ciudad con otro río. Es ahora o nunca, y nunca es un turno muy largo.' }
              : s.flags.denis_reyes
              ? { en: "Denis picked me. Denis, of all people. …A statement, immunity, a city with a different river. Say yes before I remember who I work for.", ru: 'Денис выбрал меня. Денис, надо же. …Показания, неприкосновенность, город с другой рекой. Скажите «да», пока я не вспомнила, на кого работаю.', uk: 'Денис обрав мене. Денис, треба ж. …Свідчення, недоторканність, місто з іншою річкою. Скажіть «так», поки я не згадала, на кого працюю.', es: 'Denis me eligió a mí. Denis, precisamente. …Una declaración, inmunidad, una ciudad con otro río. Diga que sí antes de que recuerde para quién trabajo.' }
              : s.flags.defied_man
              ? { en: "He called me at ten past three. 'The clerk says it ends tonight.' He was laughing. …Last offer on the sheet: a statement, immunity, a new city.", ru: 'Он позвонил мне в три десять. «Портье говорит, сегодня всё закончится». Он смеялся. …Последнее предложение в графике: показания, неприкосновенность, новый город.', uk: 'Він подзвонив мені о третій десять. «Портьє каже, сьогодні все скінчиться». Він сміявся. …Остання пропозиція в графіку: свідчення, недоторканність, нове місто.', es: 'Me llamó a las tres y diez. «{El|La} recepcionista dice que esto se acaba esta noche». Se reía. …Última oferta del horario: una declaración, inmunidad, una ciudad nueva.' }
              : { en: "Last night on the sheet. I've watched six clerks reach this night. On the sixth I make one offer: a statement, immunity, a new city. Nobody's taken it yet.", ru: 'Последняя ночь в графике. Я видела, как до неё доходят шесть портье. На шестой я делаю одно предложение: показания, неприкосновенность, новый город. Пока никто не согласился.', uk: 'Остання ніч у графіку. Я бачила, як до неї доходять шість портьє. На шостій я роблю одну пропозицію: свідчення, недоторканність, нове місто. Поки ніхто не погодився.', es: 'Última noche del horario. He visto a seis recepcionistas llegar a esta noche. En la sexta hago una sola oferta: una declaración, inmunidad, una ciudad nueva. Nadie la ha aceptado todavía.' },
             choices: (s) => s.flags.final_up
              ? [
                  { text: { en: '"Write the truth. Once."', ru: '«Напишите правду. Один раз».', uk: '«Напишіть правду. Один раз».', es: '«Escriba la verdad. Una vez».' }, next: 'truth' },
                  { text: { en: 'Say nothing.', ru: 'Молчать.', uk: 'Мовчати.', es: 'No decir nada.' }, next: 'quiet' },
                ]
              : s.flags.final_coat
              ? [
                  { text: { en: '"Tuesday. Six hotels."', ru: '«Вторник. Шесть отелей».', uk: '«Вівторок. Шість готелів».', es: '«El martes. Seis hoteles».' }, next: 'tues' },
                  { text: { en: '"Are you the badge?"', ru: '«Значок — это вы?»', uk: '«Жетон — це ви?»', es: '«¿La placa es usted?»' }, next: 'badge' },
                ]
              : s.flags.final_fire
              ? [
                  { text: { en: '"A newspaper can\'t sell me, either."', ru: '«Зато газета меня и не продаст».', uk: '«Зате газета мене й не продасть».', es: '«Un periódico tampoco puede venderme».' }, next: 'paper', effect: { trouble: 1 } },
                  { text: { en: 'Give her the photographs instead.', ru: 'Отдать фотографии ей.', uk: 'Віддати фотографії їй.', es: 'Darle a ella las fotografías.' }, next: 'gave', effect: { flags: { final_fire: false, final_witness: true } } },
                ]
              : [
                  { text: { en: '"Yes. Now, before I think about it."', ru: '«Да. Сейчас, пока не передумаю».', uk: '«Так. Зараз, поки не передумаю».', es: '«Sí. Ahora, antes de que lo piense».' }, next: 'car', effect: { flags: { final_witness: true } } },
                  s.flags.reyes_betrayed
                    ? { text: { en: '"You\'ll burn me. I\'ve read the paperwork."', ru: '«Вы меня сдадите. Бумаги я читаю внимательно».', uk: '«Ви мене здасте. Папери я читаю уважно».', es: '«Me va a quemar. He leído los papeles».' }, next: 'burn', effect: { trouble: 1, flags: { reyes_refused: true } } }
                    : { text: { en: '"You\'re working with him."', ru: '«Вы работаете с ним».', uk: '«Ви працюєте з ним».', es: '«Usted trabaja con él».' }, next: 'with', effect: { trouble: 1, flags: { reyes_refused: true } } },
                  { text: { en: '"Not with you."', ru: '«Не с вами».', uk: '«Не з вами».', es: '«Con usted no».' }, next: 'notyou', effect: { flags: { reyes_refused: true } } },
                ] },
        truth: { who: 'guest', text: { en: "The truth is a Friday nobody survives.", ru: 'Правда — это пятница, которую никто не переживает.', uk: 'Правда — це п’ятниця, якої ніхто не переживає.', es: 'La verdad es un viernes al que nadie sobrevive.' }, next: 'truth2' },
        truth2: { who: 'narr', text: { en: 'She leaves her card on the desk anyway. For Denis.', ru: 'Визитку она всё равно оставляет на стойке. Для Дениса.', uk: 'Візитівку вона все одно лишає на стійці. Для Дениса.', es: 'Aun así deja su tarjeta en el mostrador. Para Denis.' }, next: 'end' },
        quiet: { who: 'narr', text: { en: 'She waits. You wait. Denis, who has had all spring to practise, waits best. She leaves.', ru: 'Она ждёт. Вы ждёте. Денис, у которого была вся весна на тренировку, ждёт лучше всех. Она уходит.', uk: 'Вона чекає. Ви чекаєте. Денис, у якого була вся весна на тренування, чекає найкраще. Вона йде.', es: 'Ella espera. Usted espera. Denis, que ha tenido toda la primavera para practicar, es quien mejor espera. Ella se va.' }, next: 'end' },
        tues: { who: 'guest', text: { en: "I know the six. I know the seventh, too, and you'll find out about it on a Friday.", ru: 'Я знаю все шесть. И седьмой знаю, а вы узнаете о нём в какую-нибудь пятницу.', uk: 'Я знаю всі шість. І сьомий знаю, а ви дізнаєтеся про нього якоїсь п’ятниці.', es: 'Conozco los seis. También conozco el séptimo, y usted se enterará un viernes.' }, next: 'end' },
        badge: { who: 'guest', text: { en: "Three years ago I'd have arrested you for asking. …Go home. Get some sleep. Grey needs sleep.", ru: 'Три года назад я бы вас арестовала за такой вопрос. …Идите домой. Поспите. Серому нужен сон.', uk: 'Три роки тому я б вас заарештувала за таке запитання. …Ідіть додому. Поспіть. Сірому потрібен сон.', es: 'Hace tres años {lo|la} habría arrestado por preguntar. …Váyase a casa. Duerma algo. El gris necesita dormir.' }, next: 'end' },
        paper: { who: 'guest', text: { en: "…When it prints, my name will be in it. I'm telling you so you know I know. Go. Wear a different coat.", ru: '…Когда напечатают, там будет и моё имя. Говорю, чтобы вы знали, что я знаю. Идите. Наденьте другое пальто.', uk: '…Коли надрукують, там буде і моє ім’я. Кажу, щоб ви знали, що я знаю. Ідіть. Вдягніть інше пальто.', es: '…Cuando salga impreso, mi nombre estará ahí. Se lo digo para que sepa que lo sé. Váyase. Póngase otro abrigo.' }, next: 'end' },
        gave: { who: 'guest', text: { en: "Immunity. Relocation. A statement.", ru: 'Неприкосновенность. Переезд. Показания.', uk: 'Недоторканність. Переїзд. Свідчення.', es: 'Inmunidad. Traslado. Una declaración.' }, next: 'gave2' },
        gave2: { who: 'narr', text: { en: 'She says it like a prescription. She counts the photographs twice, and the second time her hands are steady.', ru: 'Она говорит это, как рецепт. Пересчитывает фотографии дважды, и во второй раз руки не дрожат.', uk: 'Вона каже це, як рецепт. Перераховує фотографії двічі, і вдруге руки не тремтять.', es: 'Lo dice como una receta. Cuenta las fotografías dos veces, y la segunda las manos no le tiemblan.' }, next: 'end' },
        car: { who: 'narr', text: (s) => s.flags.reyes_betrayed
              ? { en: 'You know what she is and you get in anyway. Sometimes the only way out of a building is with the person who owns the door.', ru: 'Вы знаете, кто она, и всё равно садитесь. Иногда единственный выход из здания — с тем, кому принадлежит дверь.', uk: 'Ви знаєте, хто вона, і все одно сідаєте. Іноді єдиний вихід із будівлі — з тим, кому належать двері.', es: 'Sabe lo que es ella y sube igual. A veces la única salida de un edificio es con quien es dueño de la puerta.' }
              : s.flags.delivered
              ? { en: "The engine's been running since four. On the back seat, a folder. Your name is on it, and a photograph of three hundred dollars in fifties.", ru: 'Мотор работает с четырёх. На заднем сиденье папка. На ней ваше имя и фотография трёхсот долларов полтинниками.', uk: 'Мотор працює з четвертої. На задньому сидінні тека. На ній ваше ім’я і фотографія трьохсот доларів п’ятдесятками.', es: 'El motor está en marcha desde las cuatro. En el asiento de atrás, una carpeta. Lleva su nombre, y una fotografía de trescientos dólares en billetes de cincuenta.' }
              : { en: "The engine has been running since four. She's had the heater on for you. It's the kindest thing anyone's done all week, and you don't trust it.", ru: 'Мотор работает с четырёх. Она включила для вас печку. Самое доброе, что кто-то сделал за неделю, и вы этому не верите.', uk: 'Мотор працює з четвертої. Вона ввімкнула для вас пічку. Найдобріше, що хтось зробив за тиждень, і ви цьому не вірите.', es: 'El motor está en marcha desde las cuatro. Le ha puesto la calefacción. Es lo más amable que alguien ha hecho en toda la semana, y usted no se fía.' },
             next: 'end' },
        burn: { who: 'guest', text: { en: "Everybody gets burned. I'm offering a lower temperature.", ru: 'Все горят. Я предлагаю температуру пониже.', uk: 'Усі горять. Я пропоную нижчу температуру.', es: 'Todo el mundo se quema. Yo le ofrezco una temperatura más baja.' }, next: 'burn2' },
        burn2: { who: 'narr', text: { en: 'She leaves the car door open a full minute before she drives off.', ru: 'Она держит дверцу машины открытой целую минуту, прежде чем уехать.', uk: 'Вона тримає дверцята машини відчиненими цілу хвилину, перш ніж поїхати.', es: 'Deja la puerta del coche abierta un minuto entero antes de irse.' }, next: 'end' },
        with: { who: 'guest', text: { en: "With. On. Under. Pick a preposition; they all pay the same. …Offer stands till the car's gone.", ru: 'С ним. Над ним. Под ним. Выберите предлог; платят за все одинаково. …Предложение в силе, пока машина у входа.', uk: 'З ним. Над ним. Під ним. Оберіть прийменник; платять за всі однаково. …Пропозиція чинна, поки машина біля входу.', es: 'Con. Tras. Bajo. Elija una preposición; todas pagan igual. …La oferta sigue en pie hasta que se vaya el coche.' }, next: 'with2' },
        with2: { who: 'narr', text: { en: 'The car goes.', ru: 'Машина уезжает.', uk: 'Машина від’їжджає.', es: 'El coche se va.' }, next: 'end' },
        notyou: { who: 'guest', text: { en: "Then with who, clerk? Name one.", ru: 'Тогда с кем, портье? Назовите хоть кого-нибудь.', uk: 'Тоді з ким, портьє? Назвіть хоч когось.', es: 'Entonces, ¿con quién, recepcionista? Nombre a alguien.' }, next: 'notyou2' },
        notyou2: { who: 'narr', text: { en: "You can't. She waits for it, longer than she should. Then she goes.", ru: 'Вы не можете. Она ждёт дольше, чем следует. Потом уходит.', uk: 'Ви не можете. Вона чекає довше, ніж варто. Потім іде.', es: 'No puede. Ella espera, más de lo que debería. Luego se va.' }, next: 'end' },
      }
    },
    {
      time: '06:00', name: { en: 'Sal (the manager)', ru: 'Сэл (управляющий)', uk: 'Сел (управитель)', es: 'Sal (el gerente)' }, voice: { gender: 'm', pitch: 0.7, rate: 1.05 },
      portrait: portrait('#7a2a2a', false, true), start: 'a',
      nodes: {
        a: { who: 'guest', text: (s) => s.flags.returned_key
              ? { en: "Morning. There's a key on my desk with a number this building doesn't have. I'm going to put it in the drawer and we're both going to forget it. Register.", ru: 'Утро. На моей стойке ключ с номером, которого в этом здании нет. Я уберу его в ящик, и мы оба забудем. Касса.', uk: 'Ранок. На моїй стійці ключ із номером, якого в цій будівлі немає. Я приберу його в шухляду, і ми обоє забудемо. Каса.', es: 'Buenos días. Hay una llave en mi mostrador con un número que este edificio no tiene. La voy a meter en el cajón y los dos nos vamos a olvidar de ella. La caja.' }
              : s.flags.silent_man
              ? { en: "Morning. Three hundred in the register that didn't come from rooms. I'm not asking. I've never asked. Register.", ru: 'Утро. В кассе триста, которые не от номеров. Я не спрашиваю. Я никогда не спрашивал. Касса.', uk: 'Ранок. У касі триста, які не від номерів. Я не питаю. Я ніколи не питав. Каса.', es: 'Buenos días. Trescientos en la caja que no salen de las habitaciones. No pregunto. Nunca he preguntado. La caja.' }
              : s.flags.sal_exposed
              ? { en: "Morning. You know about the cut, I know you know, let's do the register like adults.", ru: 'Утро. Ты знаешь про долю, я знаю, что ты знаешь, давай посчитаем кассу как взрослые люди.', uk: 'Ранок. Ти знаєш про частку, я знаю, що ти знаєш, давай порахуємо касу як дорослі люди.', es: 'Buenos días. Tú sabes lo de mi parte, yo sé que lo sabes: hagamos la caja como adultos.' }
              : s.flags.sal_cut
              ? { en: "Morning. Register. And whatever happened at three, I wasn't here for it. Per usual.", ru: 'Утро. Касса. И что бы ни было в три, меня при этом не было. Как обычно.', uk: 'Ранок. Каса. І хай що було о третій, мене при цьому не було. Як завжди.', es: 'Buenos días. La caja. Y pasara lo que pasara a las tres, yo no estaba. Como siempre.' }
              : { en: "Morning. Register. Last night on the sheet; I haven't written next week yet. On purpose.", ru: 'Утро. Касса. Последняя ночь в графике; следующую неделю я ещё не написал. Нарочно.', uk: 'Ранок. Каса. Остання ніч у графіку; наступний тиждень я ще не написав. Навмисно.', es: 'Buenos días. La caja. Última noche del horario; la semana que viene aún no la he escrito. A propósito.' },
             next: (s) => ((s.flags.final_up || s.flags.final_coat || s.flags.final_fire || s.flags.final_witness) ? 'fin' : 'b') },
        fin: { who: 'narr', text: (s) => s.flags.final_up
              ? { en: "You put the twelve key on the register. Sal looks at it, at Denis, and writes 'night clerk: D.' on next week's sheet without asking. He knows the handwriting; he wrote it once before.", ru: 'Вы кладёте ключ с биркой 12 на кассу. Сэл смотрит на него, на Дениса и, не спрашивая, пишет в графике на следующую неделю: «ночной портье: Д.». Почерк он знает; он уже писал это однажды.', uk: 'Ви кладете ключ із биркою 12 на касу. Сел дивиться на нього, на Дениса і, не питаючи, пише в графіку на наступний тиждень: «нічний портьє: Д.». Почерк він знає; він уже писав це одного разу.', es: 'Deja la llave doce sobre la caja. Sal la mira, mira a Denis y, sin preguntar, escribe en el horario de la semana que viene: «recepcionista de noche: D.». Conoce la letra; ya la escribió una vez.' }
              : s.flags.final_coat
              ? { en: "He sees the coat. He counts the register very fast. 'You won't be needing wages, then.' It is the closest he comes to goodbye.", ru: 'Он видит пальто. Считает кассу очень быстро. «Зарплата тебе, значит, не понадобится». Ближе к «прощай» он не подходит.', uk: 'Він бачить пальто. Рахує касу дуже швидко. «Зарплата тобі, отже, не знадобиться». Ближче до «прощавай» він не підходить.', es: 'Ve el abrigo. Cuenta la caja muy deprisa. «Entonces ya no vas a necesitar sueldo». Es lo más cerca que llega de una despedida.' }
              : s.flags.final_fire
              ? { en: "'Whatever you're doing, do it somewhere I can say I didn't see.' He has said that before. It has always worked before.", ru: '«Что бы там ни затевалось, пусть будет там, где я смогу сказать, что не видел». Он говорил это и раньше. Раньше всегда срабатывало.', uk: '«Хай що там затівається, нехай буде там, де я зможу сказати, що не бачив». Він казав це й раніше. Раніше завжди спрацьовувало.', es: '«Hagas lo que hagas, hazlo donde yo pueda decir que no lo vi». Ya lo ha dicho antes. Antes siempre funcionó.' }
              : { en: "Reyes's car idles outside. Sal watches it through the glass. 'Tell them I take a cut,' he says. 'Everyone else will.'", ru: 'Машина Рейес урчит у входа. Сэл смотрит на неё через стекло. «Скажи им, что я беру долю», говорит он. «Остальные всё равно скажут».', uk: 'Машина Реєс гурчить біля входу. Сел дивиться на неї крізь скло. «Скажи їм, що я беру частку», каже він. «Решта все одно скажуть».', es: 'El coche de Reyes espera fuera con el motor en marcha. Sal lo mira a través del cristal. «Diles que me llevo una parte», dice. «Los demás se lo van a decir igual».' },
             next: 'end' },
        b: { who: 'guest', text: (s) => s.flags.dana_register
              ? { en: "Register's a hundred light and I'm not asking why. So. Next week. Yes or no.", ru: 'В кассе не хватает сотни, и я не спрашиваю почему. Так. Следующая неделя. Да или нет.', uk: 'У касі бракує сотні, і я не питаю чому. Отже. Наступний тиждень. Так чи ні.', es: 'A la caja le faltan cien y no pregunto por qué. Bueno. La semana que viene. ¿Sí o no?' }
              : s.flags.marv_goes
              ? { en: "Marv's checking out. Twenty years. That leaves you as the only one in this building who talks to me. So. Next week. Yes or no.", ru: 'Марв съезжает. Двадцать лет. Больше в этом здании со мной никто не разговаривает. Так. Следующая неделя. Да или нет.', uk: 'Марв виїжджає. Двадцять років. Більше в цій будівлі зі мною ніхто не розмовляє. Отже. Наступний тиждень. Так чи ні.', es: 'Marv se va. Veinte años. Eso te deja como {el único|la única} en este edificio que me habla. Bueno. La semana que viene. ¿Sí o no?' }
              : { en: "So. Next week. Yes or no.", ru: 'Так. Следующая неделя. Да или нет.', uk: 'Отже. Наступний тиждень. Так чи ні.', es: 'Bueno. La semana que viene. ¿Sí o no?' },
             choices: (s) => [
               { text: { en: 'Put the keys on the desk. "I quit."', ru: 'Положить ключи на стойку. «Я увольняюсь».', uk: 'Покласти ключі на стійку. «Я звільняюся».', es: 'Dejar las llaves en el mostrador. «Lo dejo».' }, next: 'quit', effect: { cash: 20, flags: { final_leave: true } } },
               { text: { en: '"Same time tomorrow. And a raise."', ru: '«Завтра в то же время. И прибавку».', uk: '«Завтра о тій самій порі. І надбавку».', es: '«Mañana a la misma hora. Y con aumento».' }, next: 'raise', effect: { cash: 50, flags: { final_stay: true } } },
               { text: { en: '"You took a cut. Every night. Say it."', ru: '«Вы брали долю. Каждую ночь. Скажите это».', uk: '«Ви брали частку. Щоночі. Скажіть це».', es: '«Usted se llevaba una parte. Cada noche. Dígalo».' }, next: 'cut', effect: { trouble: 1 } },
               ...(s.flags.bus_ticket ? [
                 { text: { en: 'Put the keys and the bus ticket on the desk. "I quit. I\'m on the seven o\'clock."', ru: 'Положить на стойку ключи и билет на автобус. «Я увольняюсь. Уезжаю семичасовым».', uk: 'Покласти на стійку ключі й квиток на автобус. «Я звільняюся. Їду семигодинним».', es: 'Dejar en el mostrador las llaves y el billete de autobús. «Lo dejo. Me voy en el de las siete».' }, next: 'ticket', effect: { flags: { final_leave: true, left_by_bus: true } } },
               ] : []),
             ] },
        quit: { who: 'narr', text: (s) => (s.flags.dana_walk || s.flags.leo_suitcase)
              ? { en: "He doesn't argue. He pushes twenty across the desk. 'Bus fare. Seven, was it.' He knows; he always knows; it's the one thing he's good for.", ru: 'Он не спорит. Двигает по стойке двадцатку. «На автобус. В семь, да?» Он знает; он всегда знает; на это он и годится.', uk: 'Він не сперечається. Посуває по стійці двадцятку. «На автобус. О сьомій, так?» Він знає; він завжди знає; на це він і годиться.', es: 'No discute. Empuja veinte por el mostrador. «Para el autobús. A las siete, ¿no?». Lo sabe; siempre lo sabe; es lo único para lo que sirve.' }
              : { en: "He doesn't argue. He pushes twenty across the desk. 'Bus fare.' He doesn't ask where. Where was never his department.", ru: 'Он не спорит. Двигает по стойке двадцатку. «На автобус». Куда — не спрашивает. «Куда» никогда не было его делом.', uk: 'Він не сперечається. Посуває по стійці двадцятку. «На автобус». Куди — не питає. «Куди» ніколи не було його справою.', es: 'No discute. Empuja veinte por el mostrador. «Para el autobús». No pregunta adónde. El adónde nunca fue asunto suyo.' },
             next: 'end' },
        ticket: { who: 'narr', text: { en: "Sal reads the ticket the way he reads the register: twice, then once more for himself. The twenty he had ready goes back in the drawer. 'Open date,' he says. 'Smart. Nobody in this building ever left on the day they meant to.'", ru: 'Сэл читает билет так же, как кассу: дважды и ещё раз для себя. Двадцатка, которую он приготовил, возвращается в ящик. «Открытая дата», говорит он. «Умно. Из этого здания ещё никто не уехал в тот день, в какой собирался».', uk: 'Сел читає квиток так само, як касу: двічі й ще раз для себе. Двадцятка, яку він приготував, повертається в шухляду. «Відкрита дата», каже він. «Розумно. З цієї будівлі ще ніхто не поїхав того дня, коли збирався».', es: 'Sal lee el billete como lee la caja: dos veces, y una más para él. Los veinte que tenía preparados vuelven al cajón. «Fecha abierta», dice. «Bien pensado. En este edificio nadie se ha ido nunca el día que pensaba».' }, next: 'end' },
        raise: { who: 'guest', text: { en: "Fifty a week. Don't tell Marv.", ru: 'Пятьдесят в неделю. Марву не говори.', uk: 'П’ятдесят на тиждень. Марву не кажи.', es: 'Cincuenta a la semana. No se lo digas a Marv.' }, next: 'raise2' },
        raise2: { who: 'narr', text: { en: "He writes your name on next week's sheet. In pen. He has never used pen before.", ru: 'Он вписывает ваше имя в график на следующую неделю. Ручкой. Раньше он ручкой не писал.', uk: 'Він вписує ваше ім’я в графік на наступний тиждень. Ручкою. Раніше він ручкою не писав.', es: 'Escribe su nombre en el horario de la semana que viene. Con bolígrafo. Nunca antes había usado bolígrafo.' }, next: 'end' },
        cut: { who: 'guest', text: { en: "I take a cut. Everybody takes a cut. The building takes a cut.", ru: 'Я беру долю. Все берут долю. Здание берёт долю.', uk: 'Я беру частку. Усі беруть частку. Будівля бере частку.', es: 'Me llevo una parte. Todo el mundo se lleva una parte. El edificio se lleva una parte.' }, next: 'cut2' },
        cut2: { who: 'narr', text: { en: "He puts the register away. He does not write next week. He does not tear it up either.", ru: 'Он убирает кассу. Следующую неделю не пишет. Но и не рвёт.', uk: 'Він прибирає касу. Наступний тиждень не пише. Але й не рве.', es: 'Guarda la caja. No escribe la semana que viene. Tampoco la rompe.' }, next: 'end' },
      }
    },
  ],
  pickEnding(state) {
    const f = state.flags;
    if (state.trouble >= TROUBLE_MAX) return 'fired';
    // What the player chose tonight, in a scene, comes first.
    if (f.final_up) return 'room_twelve';
    if (f.final_coat) return 'grey_coat';
    if (f.final_fire) return 'fire';
    if (f.final_witness) return (f.reyes_betrayed || f.delivered) ? 'fall_guy' : 'witness';
    if (f.final_leave) return 'clean';
    if (f.final_stay) return 'desk';
    // Nobody chose. Six nights choose.
    if (f.becoming_grey && !f.refused_grey) return 'grey_coat';
    if (f.took_photos && f.denis_ally && !f.reyes_deal && !f.denis_wait) return 'fire';
    if (f.reyes_deal && !f.reyes_refused && (f.reyes_betrayed || f.delivered)) return 'fall_guy';
    if (f.reyes_deal && !f.reyes_refused) return 'witness';
    if (f.marked || f.threatened) return 'marked';
    if ((!f.has_key || f.returned_key) && !f.delivered && !f.reyes_deal && !f.becoming_grey && !f.went_up) return 'clean';
    return 'desk';
  },
  endings: {
    fired: {
      en: ['SHIFT OVER', "Sal counts the week's trouble before he counts the cash: you lasted until the last night on the sheet. 'Six nights. Almost.' He doesn't write next week. The man in the good coat holds the door for you on the way out."],
      ru: ['СМЕНА ОКОНЧЕНА', 'Сэл считает проблемы за неделю раньше, чем деньги: вы продержались до последней ночи по графику. «Шесть ночей. Почти дотянул{|а}». Следующую неделю он не пишет. Мужчина в хорошем пальто придерживает вам дверь на выходе.'],
      uk: ['ЗМІНУ ЗАКІНЧЕНО', 'Сел рахує проблеми за тиждень раніше, ніж гроші: ви протрималися до останньої ночі за графіком. «Шість ночей. Майже дотягнув{|ла}». Наступний тиждень він не пише. Чоловік у гарному пальті притримує вам двері на виході.'], es: ['FIN DEL TURNO', 'Sal cuenta los problemas de la semana antes que el dinero: usted aguantó hasta la última noche del horario. «Seis noches. Casi lo logras». No escribe la semana que viene. El hombre del abrigo bueno le sostiene la puerta al salir.'] },
    grey_coat: {
      en: ['THE GREY COAT', "The coat fits; it always fits. On a Tuesday, in a lobby that smells of wet carpet, you set an envelope in front of a new night clerk: 'This stays behind your desk until tomorrow night.' They have an honest face, and you know exactly what those cost."],
      ru: ['СЕРОЕ ПАЛЬТО', 'Пальто сидит; оно всегда сидит. Во вторник, в холле, где пахнет мокрым ковром, вы кладёте конверт перед новым ночным портье: «Это лежит у вас за стойкой до завтрашней ночи». Лицо у портье честное, и вы точно знаете, сколько такие стоят.'],
      uk: ['СІРЕ ПАЛЬТО', 'Пальто сидить; воно завжди сидить. У вівторок, у холі, де пахне мокрим килимом, ви кладете конверт перед новим нічним портьє: «Це лежить у вас за стійкою до завтрашньої ночі». Обличчя в портьє чесне, і ви точно знаєте, скільки такі коштують.'], es: ['EL ABRIGO GRIS', 'El abrigo le queda bien; siempre queda bien. Un martes, en un vestíbulo que huele a moqueta mojada, deja un sobre delante de un nuevo recepcionista de noche: «Esto se queda detrás de su mostrador hasta mañana por la noche». Tiene una cara honrada, y usted sabe exactamente lo caras que salen.'] },
    room_twelve: {
      en: ['ROOM TWELVE', "You go up and you do not come down. The rules are on the back of the door; you read them on the second night, like he did. Downstairs, Denis clicks the lamp on at eleven and says 'there is no room twelve' at three, and means it kindly. Somebody should be kind about it."],
      ru: ['ДВЕНАДЦАТЫЙ НОМЕР', 'Вы поднимаетесь и не спускаетесь. Правила на обратной стороне двери; вы читаете их на вторую ночь, как и он. Внизу Денис включает лампу в одиннадцать и говорит «двенадцатого номера нет» в три, и говорит это по-доброму. Кто-то должен быть добрым хотя бы в этом.'],
      uk: ['ДВАНАДЦЯТИЙ НОМЕР', 'Ви піднімаєтеся і не спускаєтеся. Правила на звороті дверей; ви читаєте їх другої ночі, як і він. Унизу Денис вмикає лампу об одинадцятій і каже «дванадцятого номера немає» о третій, і каже це по-доброму. Хтось має бути добрим хоча б у цьому.'], es: ['LA HABITACIÓN DOCE', 'Sube y no vuelve a bajar. Las reglas están detrás de la puerta; las lee la segunda noche, como él. Abajo, Denis enciende la lámpara a las once y a las tres dice «no hay habitación doce», y lo dice con cariño. Alguien debería hacerlo con amabilidad.'] },
    fire: {
      en: ['THE FIRE', "Denis's reporter meets you at the diner in a coat that isn't yours. Nine days later the hotel is on the front page: seventeen photographs, a door with no number, a manager in handcuffs still saying 'the building takes a cut'. Officer Reyes is in the third paragraph, and she does not call to complain. You leave town on the seven o'clock bus with a newspaper you don't need to read."],
      ru: ['ПОЖАР', 'Репортёр Дениса встречает вас в закусочной; на вас чужое пальто. Через девять дней отель на первой полосе: семнадцать фотографий, дверь без номера, управляющий в наручниках, который всё повторяет: «здание берёт долю». Офицер Рейес — в третьем абзаце, и она не звонит жаловаться. Вы уезжаете из города семичасовым автобусом с газетой, которую вам не нужно читать.'],
      uk: ['ПОЖЕЖА', 'Репортерка Дениса зустрічає вас у закусочній; на вас чуже пальто. Через дев’ять днів готель на першій шпальті: сімнадцять фотографій, двері без номера, управитель у наручниках, який усе повторює: «будівля бере частку». Офіцер Реєс — у третьому абзаці, і вона не дзвонить скаржитися. Ви їдете з міста семигодинним автобусом із газетою, яку вам не треба читати.'], es: ['EL INCENDIO', 'La periodista de Denis se reúne con usted en la cafetería; usted lleva un abrigo que no es suyo. Nueve días después, el hotel está en primera plana: diecisiete fotografías, una puerta sin número, un gerente esposado que sigue repitiendo «el edificio se lleva una parte». La agente Reyes aparece en el tercer párrafo, y no llama para quejarse. Se va de la ciudad en el autobús de las siete con un periódico que no necesita leer.'] },
    // Variant endings are functions of state; the title must stay the same string in every variant (the sim counts by title).
    witness: (s) => s.flags.took_late
      ? {
        en: ['THE WITNESS', "Relocation turns out to mean a smaller apartment in a city with a different river. Nobody ever asks about the five hundred from the second night; it never reached anyone, which is the only clean thing about it. Two blocks from the apartment there is a small hotel that needs a night clerk, and you are very good at that. On the first night, at eleven, a woman in grey comes in without shaking the rain off. You already know what she's going to say."],
        ru: ['СВИДЕТЕЛЬ', 'Переезд оказывается квартирой поменьше в городе с другой рекой. О пятистах со второй ночи никто так и не спрашивает; они ни до кого не дошли, и это единственное чистое в них. В двух кварталах от квартиры маленький отель, которому нужен ночной портье, а это вы умеете. В первую ночь, в одиннадцать, входит женщина в сером и не стряхивает дождь. Вы уже знаете, что она скажет.'],
        uk: ['СВІДОК', 'Переїзд виявляється меншою квартирою в місті з іншою річкою. Про п’ятсот із другої ночі ніхто так і не питає; вони ні до кого не дійшли, і це єдине чисте в них. За два квартали від квартири маленький готель, якому потрібен нічний портьє, а це ви вмієте. Першої ночі, об одинадцятій, заходить жінка в сірому і не струшує дощ. Ви вже знаєте, що вона скаже.'], es: ['{EL TESTIGO|LA TESTIGO}', 'El traslado resulta ser un apartamento más pequeño en una ciudad con otro río. Nadie pregunta nunca por los quinientos de la segunda noche; nunca llegaron a nadie, y es lo único limpio que tienen. A dos calles del apartamento hay un hotel pequeño que necesita un recepcionista de noche, y a usted eso se le da muy bien. La primera noche, a las once, entra una mujer de gris sin sacudirse la lluvia. Usted ya sabe lo que va a decir.'] }
      : {
        en: ['THE WITNESS', "Relocation turns out to mean a smaller apartment in a city with a different river. Two blocks from it there is a small hotel that needs a night clerk, and you are very good at that. On the first night, at eleven, a woman in grey comes in without shaking the rain off. You already know what she's going to say."],
        ru: ['СВИДЕТЕЛЬ', 'Переезд оказывается квартирой поменьше в городе с другой рекой. В двух кварталах от неё маленький отель, которому нужен ночной портье, а это вы умеете. В первую ночь, в одиннадцать, входит женщина в сером и не стряхивает дождь. Вы уже знаете, что она скажет.'],
        uk: ['СВІДОК', 'Переїзд виявляється меншою квартирою в місті з іншою річкою. За два квартали від неї маленький готель, якому потрібен нічний портьє, а це ви вмієте. Першої ночі, об одинадцятій, заходить жінка в сірому і не струшує дощ. Ви вже знаєте, що вона скаже.'], es: ['{EL TESTIGO|LA TESTIGO}', 'El traslado resulta ser un apartamento más pequeño en una ciudad con otro río. A dos calles hay un hotel pequeño que necesita un recepcionista de noche, y a usted eso se le da muy bien. La primera noche, a las once, entra una mujer de gris sin sacudirse la lluvia. Usted ya sabe lo que va a decir.'] },
    fall_guy: {
      en: ['THE FALL GUY', "The statement is typed up neatly; your name is on every page and Reyes's is on none of them. It turns out the desk was photographed from more angles than the envelope. 'Everybody gets burned,' she says outside the courtroom, not unkindly. 'I offered you a lower temperature.'"],
      ru: ['КОЗЁЛ ОТПУЩЕНИЯ', 'Показания аккуратно перепечатаны; ваше имя на каждой странице, имени Рейес нет ни на одной. Оказывается, стойку фотографировали с большего числа ракурсов, чем конверт. «Все горят», говорит она у зала суда, без злобы. «Я предлагала температуру пониже».'],
      uk: ['ЦАП-ВІДБУВАЙЛО', 'Свідчення акуратно передруковано; ваше ім’я на кожній сторінці, імені Реєс немає на жодній. Виявляється, стійку фотографували з більшої кількості ракурсів, ніж конверт. «Усі горять», каже вона біля зали суду, без злості. «Я пропонувала нижчу температуру».'], es: ['EL CHIVO EXPIATORIO', 'La declaración está pasada a limpio; su nombre aparece en cada página y el de Reyes en ninguna. Resulta que al mostrador lo fotografiaron desde más ángulos que al sobre. «Todo el mundo se quema», dice ella a la salida del juzgado, sin mala intención. «Yo le ofrecí una temperatura más baja».'] },
    // left_by_bus (Sal scene, bus ticket bought in a morning): same ending, the first sentence is the player's own ticket instead of Sal's twenty.
    clean: (s) => ((e) => (s.flags.left_by_bus ? Object.fromEntries(Object.entries(e).map(([l, [h, x]]) => [l, [h, x.replace(/^[^.]+\./, { en: "You quit at dawn with a ticket you paid for yourself; Sal's twenty stays in his drawer.", ru: "Вы увольняетесь на рассвете с билетом, за который заплатили сами; двадцатка Сэла остаётся у него в ящике.", uk: "Ви звільняєтеся на світанку з квитком, за який заплатили самі; двадцятка Села лишається в його шухляді.", es: "Deja el trabajo al amanecer con un billete que pagó de su bolsillo; los veinte de Sal se quedan en su cajón." }[l])]])) : e))(
  (s.flags.dana_walk || s.flags.leo_suitcase)
      ? {
        en: ['CLEAN', "You quit at dawn with twenty dollars of Sal's bus fare in your pocket. At seven you walk Dana to the station; there is one suitcase, and Leo carries it, because he is seventeen and it is what he can do. Nobody photographs any of it. Somewhere in the city, a different night clerk is saying yes."],
        ru: ['ЧИСТО', 'Вы увольняетесь на рассвете с двадцаткой Сэла на автобус в кармане. В семь вы провожаете Дану до автовокзала; чемодан один, и несёт его Лео, потому что ему семнадцать и это то, что он может. Никто этого не фотографирует. Где-то в городе другой ночной портье говорит «да».'],
        uk: ['ЧИСТО', 'Ви звільняєтеся на світанку з двадцяткою Села на автобус у кишені. О сьомій ви проводжаєте Дану до автовокзалу; валіза одна, і несе її Лео, бо йому сімнадцять і це те, що він може. Ніхто цього не фотографує. Десь у місті інший нічний портьє каже «так».'], es: ['{LIMPIO|LIMPIA}', 'Deja el trabajo al amanecer con los veinte dólares de Sal para el autobús en el bolsillo. A las siete acompaña a Dana a la estación; hay una sola maleta, y la lleva Leo, porque tiene diecisiete años y es lo que puede hacer. Nadie fotografía nada de esto. En algún lugar de la ciudad, otro recepcionista de noche está diciendo que sí.'] }
      : {
        en: ['CLEAN', "You quit at dawn with twenty dollars of Sal's bus fare in your pocket. At seven you are at the station alone, with nothing worth carrying. Nobody photographs any of it. Somewhere in the city, a different night clerk is saying yes."],
        ru: ['ЧИСТО', 'Вы увольняетесь на рассвете с двадцаткой Сэла на автобус в кармане. В семь вы на автовокзале {один|одна}, и нести вам нечего. Никто этого не фотографирует. Где-то в городе другой ночной портье говорит «да».'],
        uk: ['ЧИСТО', 'Ви звільняєтеся на світанку з двадцяткою Села на автобус у кишені. О сьомій ви на автовокзалі {сам|сама}, і нести вам нічого. Ніхто цього не фотографує. Десь у місті інший нічний портьє каже «так».'], es: ['{LIMPIO|LIMPIA}', 'Deja el trabajo al amanecer con los veinte dólares de Sal para el autobús en el bolsillo. A las siete está {solo|sola} en la estación, sin nada que valga la pena cargar. Nadie fotografía nada de esto. En algún lugar de la ciudad, otro recepcionista de noche está diciendo que sí.'] }),
    desk: {
      en: ['THE DESK', "You stay. You know there is a floor this building does not admit to, and that someone is paid to keep it, and you write 'no room twelve' in a hand that no longer shakes. The man nods on his way in every night, the way you nod at Marv. Sal gives you a raise and never says what for."],
      ru: ['СТОЙКА', 'Вы остаётесь. Вы знаете, что в этом здании есть этаж, которого оно не признаёт, и что кому-то платят его держать, и пишете «двенадцатого номера нет» рукой, которая больше не дрожит. Мужчина кивает вам на входе каждую ночь, как вы киваете Марву. Сэл даёт вам прибавку и не говорит за что.'],
      uk: ['СТІЙКА', 'Ви лишаєтеся. Ви знаєте, що в цій будівлі є поверх, якого вона не визнає, і що комусь платять його тримати, і пишете «дванадцятого номера немає» рукою, яка більше не тремтить. Чоловік киває вам на вході щоночі, як ви киваєте Марву. Сел дає вам надбавку і не каже за що.'], es: ['EL MOSTRADOR', 'Se queda. Sabe que hay un piso que este edificio no reconoce, y que a alguien le pagan por guardarlo, y escribe «no hay habitación doce» con una mano que ya no tiembla. Cada noche, al entrar, el hombre le hace un gesto con la cabeza, como usted se lo hace a Marv. Sal le sube el sueldo y nunca dice por qué.'] },
    marked: {
      en: ['MARKED', "Nothing was decided, which is a decision. He knows where you stand, every night, and now so do you. You lock the front door at dawn out of habit; the habit is new. It does not help. It never did."],
      ru: ['{ПОМЕЧЕН|ПОМЕЧЕНА}', 'Ничего не решено, а это тоже решение. Он знает, где вы стоите, каждую ночь, и теперь знаете вы. На рассвете вы запираете входную дверь по привычке; привычка новая. Это не помогает. Никогда не помогало.'],
      uk: ['{ПОЗНАЧЕНИЙ|ПОЗНАЧЕНА}', 'Нічого не вирішено, а це теж рішення. Він знає, де ви стоїте, щоночі, і тепер знаєте ви. На світанку ви замикаєте вхідні двері за звичкою; звичка нова. Це не допомагає. Ніколи не допомагало.'], es: ['{MARCADO|MARCADA}', 'No se decidió nada, y eso es una decisión. Él sabe dónde está usted, cada noche, y ahora usted también. Al amanecer cierra con llave la puerta de entrada por costumbre; la costumbre es nueva. No sirve de nada. Nunca sirvió.'] },
  },
});

// Money coda for the finale: one extra sentence under the ending, based on what the week actually paid.
// total = every night's register added up; key = the ending key chosen by pickEnding.
NIGHTS[NIGHTS.length - 1].coda = function (total, key, s) {
  const t = '$' + total;
  if (key === 'clean' && s && s.flags.bus_ticket) return total >= 500
    ? { en: `You leave ${t} of the week's register on the desk, under the bell, and keep the ticket. Of everything the week paid for, it is the one thing you bought for yourself.`, ru: `${t} недельной кассы вы оставляете на стойке, под звонком, а билет забираете. Из всего, за что платила эта неделя, только его вы купили для себя.`, uk: `${t} тижневої каси ви лишаєте на стійці, під дзвінком, а квиток забираєте. З усього, за що платив цей тиждень, тільки його ви купили для себе.`, es: `Deja ${t} de la caja de la semana en el mostrador, bajo el timbre, y se queda con el billete. De todo lo que pagó esta semana, es lo único que compró para sí.` }
    : { en: `The week paid ${t}, less what you spent in the mornings. The ticket was the best of it.`, ru: `Неделя принесла ${t}, за вычетом утренних трат. Билет — лучшая из них.`, uk: `Тиждень приніс ${t}, за вирахуванням ранкових витрат. Квиток — найкраща з них.`, es: `La semana pagó ${t}, descontado lo que gastó por las mañanas. El billete fue lo mejor de todo.` };
  if (key === 'fired') return { en: `Six nights paid ${t}. Sal keeps the last one against the week's trouble.`, ru: `Шесть ночей принесли ${t}. Последнюю Сэл оставляет себе, в счёт недельных проблем.`, uk: `Шість ночей принесли ${t}. Останню Сел лишає собі, в рахунок проблем за тиждень.`, es: `Seis noches pagaron ${t}. Sal se queda la última a cuenta de los problemas de la semana.` };
  if (key === 'room_twelve') return { en: `${t} stays in the drawer downstairs. Denis will find it. He will not spend it.`, ru: `${t} остаются в ящике внизу. Денис их найдёт. И не потратит.`, uk: `${t} лишаються в шухляді внизу. Денис їх знайде. І не витратить.`, es: `${t} se quedan en el cajón de abajo. Denis los encontrará. No los gastará.` };
  if (key === 'grey_coat') return total >= 1000
    ? { en: `The week paid ${t}. From now on you will not count. That is what the coat is for.`, ru: `Неделя принесла ${t}. С этого дня вы не считаете. Для этого и пальто.`, uk: `Тиждень приніс ${t}. Відтепер ви не рахуєте. Для цього й пальто.`, es: `La semana pagó ${t}. A partir de ahora no contará. Para eso es el abrigo.` }
    : { en: `The week paid ${t}. The coat pays better. That was never the point, and now it is.`, ru: `Неделя принесла ${t}. Пальто платит лучше. Дело было не в этом, а теперь в этом.`, uk: `Тиждень приніс ${t}. Пальто платить краще. Річ була не в цьому, а тепер у цьому.`, es: `La semana pagó ${t}. El abrigo paga mejor. Nunca se trató de eso, y ahora sí.` };
  if (key === 'desk') return total >= 700
    ? { en: `${t} for the week, and Sal's raise on top. You are, by the standards of this lobby, rich. You do not feel it.`, ru: `${t} за неделю и сверху прибавка Сэла. По меркам этого холла вы богаты. Вы этого не чувствуете.`, uk: `${t} за тиждень і зверху надбавка Села. За мірками цього холу ви багаті. Ви цього не відчуваєте.`, es: `${t} en la semana, y encima el aumento de Sal. Para lo que es este vestíbulo, es usted {rico|rica}. No lo nota.` }
    : { en: `${t} for the week, and Sal's raise on top. It is enough to stay. It was always enough to stay.`, ru: `${t} за неделю и сверху прибавка Сэла. Этого хватает, чтобы остаться. Всегда хватало.`, uk: `${t} за тиждень і зверху надбавка Села. Цього вистачає, щоб лишитися. Завжди вистачало.`, es: `${t} en la semana, y encima el aumento de Sal. Alcanza para quedarse. Siempre alcanzó para quedarse.` };
  if (key === 'clean') return total >= 500
    ? { en: `You leave ${t} of the week's register on the desk, under the bell. Clean means clean.`, ru: `${t} недельной кассы вы оставляете на стойке, под звонком. Чисто значит чисто.`, uk: `${t} тижневої каси ви лишаєте на стійці, під дзвінком. Чисто означає чисто.`, es: `Deja ${t} de la caja de la semana en el mostrador, bajo el timbre. Limpio es limpio.` }
    : { en: `The week paid ${t}. Most of it was rooms. You take what was yours, which is not much, and it is enough for the bus.`, ru: `Неделя принесла ${t}. Почти всё за номера. Вы берёте своё, а это немного, и на автобус хватает.`, uk: `Тиждень приніс ${t}. Майже все за номери. Ви берете своє, а це небагато, і на автобус вистачає.`, es: `La semana pagó ${t}. Casi todo fueron habitaciones. Se lleva lo que era suyo, que no es mucho, y alcanza para el autobús.` };
  if (key === 'witness' || key === 'fall_guy') return { en: `${t} from the week is logged as evidence. You will not see it again, and neither will the log.`, ru: `${t} за неделю оформлены как вещдок. Вы их больше не увидите, и опись тоже.`, uk: `${t} за тиждень оформлено як речовий доказ. Ви їх більше не побачите, і опис теж.`, es: `${t} de la semana quedan registrados como prueba. No volverá a verlos, y el registro tampoco.` };
  if (key === 'fire') return { en: `The paper mentions ${t}: the register, photographed next to the door. You never got any of it. It reads better that way.`, ru: `Газета упоминает ${t}: касса, снятая рядом с дверью. Вы из них не получили ничего. Так лучше читается.`, uk: `Газета згадує ${t}: каса, знята поруч із дверима. Ви з них не отримали нічого. Так краще читається.`, es: `El periódico menciona ${t}: la caja, fotografiada junto a la puerta. A usted nunca le llegó nada. Así se lee mejor.` };
  return total >= 800
    ? { en: `The week paid ${t}. Too much for rooms. Anyone who counts can tell, and he counts.`, ru: `Неделя принесла ${t}. Слишком много для номеров. Любой, кто считает, поймёт, а он считает.`, uk: `Тиждень приніс ${t}. Забагато для номерів. Будь-хто, хто рахує, зрозуміє, а він рахує.`, es: `La semana pagó ${t}. Demasiado para habitaciones. Cualquiera que cuente se da cuenta, y él cuenta.` }
    : { en: `The week paid ${t}. Rooms, mostly. Nothing you would have to explain.`, ru: `Неделя принесла ${t}. В основном номера. Ничего, что пришлось бы объяснять.`, uk: `Тиждень приніс ${t}. Здебільшого номери. Нічого, що довелося б пояснювати.`, es: `La semana pagó ${t}. Sobre todo habitaciones. Nada que tuviera que explicar.` };
};
